local config = {
  ui_story_5058_50580101_1_dialog_content = "\"Como você está, velho amigo? Não tenho notícias suas há muito tempo.\"",
  ui_story_5058_50580101_2_dialog_content = "\"Ainda sou o mesmo. Como você sabe, nós mercenários recebemos muitas missões estranhas.\"",
  ui_story_5058_50580101_3_dialog_content = "\"Não tenho muito tempo livre disponível, mas apenas conseguir pintar alguns traços por dia já é suficiente para mim.\"",
  ui_story_5058_50580101_4_dialog_content = "\"É só que eu não consegui encontrar mais ninguém que compartilhe meu interesse por insetos como você.\"",
  ui_story_5058_50580101_X4_dialog_content = "\"Isso me faz sentir um pouco solitário.\"",
  ui_story_5058_50580101_5_dialog_content = "\"No entanto, fiz novos amigos, como PlayerName.\"",
  ui_story_5058_50580101_X5_dialog_content = "\"Vou apresentar vocês dois quando tiver a chance.\"",
  ui_story_5058_50580101_6_dialog_content = "\"Mas eu divago. Ouvi falar da borboleta chamada <color=#FFB400>Deusa Denuo</color> recentemente.\"",
  ui_story_5058_50580101_7_dialog_content = "\"Um lugar chamado <color=#FFB400>Resort Vale Denuo</color> anunciou que a deslumbrante borboleta poderia ser vista lá...\"",
  ui_story_5058_50580101_8_dialog_content = "\"Também se alegava que avistar um traria boa sorte e as bênçãos da deusa.\"",
  ui_story_5058_50580101_9_dialog_content = "\"Claro que é obviamente puro exagero, mas eu me lembrei de você mencionando essa espécie de borboleta.\"",
  ui_story_5058_50580101_10_dialog_content = "\"Even embora você nunca tenha me revelado a conexão entre eles e sua enigmática cidade natal...\"",
  ui_story_5058_50580101_11_dialog_content = "\"De qualquer forma, espero que a notícia seja útil para você e que tenhamos a chance de nos encontrar novamente.\"",
  ui_story_5058_50580101_12_dialog_content = "\"Aguardando sua resposta.\"",
  ui_story_5058_50580101_13_dialog_content = "Não consigo acreditar que alguém sentiria falta de alguém como eu.",
  ui_story_5058_50580101_14_dialog_content = "Mas como vou te explicar o que estou fazendo agora, Luke...?",
  ui_story_5058_50580101_15_dialog_content = "Se importa de vir aqui por um minuto, Cena?",
  ui_story_5058_50580101_16_dialog_content = "O <color=#FFB400>convite</color> que mencionei está feito. Por favor, envie-o para mim!",
  ui_story_5058_50580101_17_dialog_content = "Claro, chefe, vai fazer!",
  ui_story_5058_50580101_18_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5058_50580101_19_dialog_content = "Você tem certeza de que estamos no lugar certo, PlayerName? Eu nem vejo nada que se pareça com uma casa normal...",
  ui_story_5058_50580101_20_dialog_content = "Simplesmente não grita \"o resort premium para ver a Deusa Denuo!\" para mim.",
  ui_story_5058_50580101_21_dialog_content = "Bem, é aqui que as coordenadas apontavam...",
  ui_story_5058_50580101_22_dialog_content = "Você comprou os ingressos por canais legítimos?",
  ui_story_5058_50580101_23_option_content = "Eu garanti isso!",
  ui_story_5058_50580101_24_dialog_content = "Então, o que é esse <color=#FFB400>convite</color> que você está segurando?",
  ui_story_5058_50580101_25_dialog_content = "O resort me enviou, então deve ser legítimo, não é?",
  ui_story_5058_50580101_26_option_content = "Bom...",
  ui_story_5058_50580101_27_dialog_content = "Recebi este <color=#FFB400>convite</color> para mim nas mensagens, então deve ser legítimo, não é?",
  ui_story_5058_50580101_28_dialog_content = "Hã? Vejamos...",
  ui_story_5058_50580101_29_dialog_content = "\"Prezado PlayerName, temos o prazer de anunciar que o tão esperado Denuo Valley Resort está finalmente concluído!\"",
  ui_story_5058_50580101_30_dialog_content = "\"O local inclui um enorme parque de diversões e um hotel premium.\"",
  ui_story_5058_50580101_31_dialog_content = "\"Convidamos você sinceramente para experimentar todas as comodidades e serviços que temos a oferecer na casa, antes de abrirmos ao público!\"",
  ui_story_5058_50580101_32_dialog_content = "\"Junto com este convite estão três passes VIP. Sinta-se à vontade para trazer sua família ou amigos.\"",
  ui_story_5058_50580101_33_dialog_content = "\"Toda a equipe do Denuo Valley Resort aguarda sua chegada!\"",
  ui_story_5058_50580101_34_dialog_content = "\"Proprietário Principal: Lorelei Cardogon\"?",
  ui_story_5058_50580101_35_dialog_content = "Eu estava me perguntando por que você teria ingressos para um resort ainda não inaugurado, PlayerName.",
  ui_story_5058_50580101_36_dialog_content = "Então, eram realmente passes gratuitos... Eu pensei que você tivesse usado suas economias.",
  ui_story_5058_50580101_37_dialog_content = "Mas isso parece bom demais para ser verdade. Acho que é um desses golpes mais recentes, ou...",
  ui_story_5058_50580101_38_dialog_content = "Espere, e se houver bandidos escondidos esperando para nos emboscar?",
  ui_story_5058_50580101_39_dialog_content = "Ei, espere um pouco. Isso não é território da Chave Rediesel?",
  ui_story_5058_50580101_40_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5058_50580101_41_dialog_content = "Nós realmente vamos pegar bandidos de verdade?!",
  ui_story_5058_50580101_42_dialog_content = "Bandidos? Bem, você está absolutamente certo no sentido de que um bandido está presente para roubar os corações das senhoras... mas esse não é o ponto.",
  ui_story_5058_50580101_43_dialog_content = "Estávamos ansiosos pela sua visita, PlayerName, e finalmente, aqui está você hoje.",
  ui_story_5058_50580101_44_dialog_content = "As encantadoras jovens senhoras com você devem ser Vice e Carleen, presumo?",
  ui_story_5058_50580101_45_dialog_content = "Quem é você?",
  ui_story_5058_50580101_46_dialog_content = "Peço desculpas por não ter me apresentado corretamente. Eu sou Cena, <color=#FFB400>gerente geral</color> do Denuo Valley Resort.",
  ui_story_5058_50580101_47_dialog_content = "Ah, graças a Deus, os ingressos eram legítimos! Mas será que este lugar é realmente um resort? Não corresponde exatamente à descrição no folheto...",
  ui_story_5058_50580101_48_dialog_content = "Hahaha, o Vale Denuo pode ser bastante traiçoeiro até mesmo para os Eclipsitas. Não é um lugar fácil de encontrar.",
  ui_story_5058_50580101_49_dialog_content = "EveEmbora tenhamos organizado traslados para nossos convidados de todos os quatro cantos do mundo...",
  ui_story_5058_50580101_50_dialog_content = "O chefe instruiu-me especificamente para vir buscá-lo pessoalmente, já que você é nosso principal VIP.",
  ui_story_5058_50580101_X50_dialog_content = "Nosso ilustre convidado tem alguma pergunta?",
  ui_story_5058_50580101_51_option_content = "O chefe?",
  ui_story_5058_50580101_52_dialog_content = "É aquela a Sra. Lorelei Cardogon no convite?",
  ui_story_5058_50580101_53_dialog_content = "Sim. A Srta. Lorelei é a filha mais velha da família Cardogon e da reputação imobiliária, além de ser a principal proprietária do Denuo Valley Resort.",
  ui_story_5058_50580101_54_dialog_content = "É preciso alguém impressionante para construir um resort gigante, mas esta é a primeira vez que ouço esse nome.",
  ui_story_5058_50580101_55_dialog_content = "O que não é incomum, na verdade. Os Cardogons são discretos, mas têm investimentos em todo Astra. Seu nome geralmente é conhecido apenas por insiders do mundo dos negócios.",
  ui_story_5058_50580101_56_dialog_content = "Mas a Srta. Lorelei não contou com a ajuda de sua família para essa empreitada. Ela mesma atraiu investimentos externos para lançar a instalação.",
  ui_story_5058_50580101_57_dialog_content = "Ela faz tudo isso independente da família? Que coragem!",
  ui_story_5058_50580101_X57_dialog_content = "Isso mesmo.",
  ui_story_5058_50580101_58_option_content = "Sou um VIP premier?",
  ui_story_5058_50580101_X59_dialog_content = "Isso é um exagero...",
  ui_story_5058_50580101_59_dialog_content = "PlayerName, sua reputação é conhecida em toda Astra e se espalhou até mesmo para o extremo leste.",
  ui_story_5058_50580101_60_dialog_content = "O chefe tem sido um fã seu... Não, qual é a palavra de novo?",
  ui_story_5058_50580101_61_dialog_content = "Ah, entendi, um Lovegator!",
  ui_story_5058_50580101_62_dialog_content = "Estou lisonjeado! Mas seu chefe tem uma perspectiva ampla para saber até essas coisas.",
  ui_story_5058_50580101_X61_dialog_content = "De fato!",
  ui_story_5058_50580101_X62_dialog_content = "Ah, você também mencionou...",
  ui_story_5058_50580101_63_option_content = "Um ônibus?",
  ui_story_5058_50580101_64_dialog_content = "Isso significa que temos que pegar uma carona... O resort fica longe daqui?",
  ui_story_5058_50580101_65_dialog_content = "Eu não diria longe, mas chegar lá pode ser um pouco aventureiro. Apenas esteja preparado. Acho que você também pode chamar a viagem de emocionante.",
  ui_story_5058_50580101_66_dialog_content = "Não vamos correr a cem milhas por hora neste lugar árido e desolado novamente, vamos? Onde estão as cachoeiras e lagos? Cadê as férias frescas de verão que eu desejava?",
  ui_story_5058_50580101_67_dialog_content = "EveTudo o que você procura está no Vale Denuo. Já que está ansioso para chegar lá, entre no ônibus espacial!",
  ui_story_5058_50580101_68_dialog_content = "Quanto antes chegarmos lá, mais cedo podemos começar a nos divertir, não é?",
  ui_story_5058_50580101_69_dialog_content = "Ah, vamos lá, não faça essa cara de que vai vomitar antes mesmo de entrar no carro! Só pra você saber, todo mundo gosta da minha direção.",
  ui_story_5058_50580101_70_dialog_content = "Ah, mais uma coisa... Olhem para cá, ilustres convidados, e digam: \"Xis!\"",
  ui_story_5058_50580101_71_dialog_content = "Hã?",
  ui_story_5058_50580101_72_dialog_content = "Você precisa tirar fotos para lembrar das férias!",
  ui_story_5058_50580101_73_dialog_content = "Isso é tão atencioso... Tenho a sensação de que vamos nos divertir muito aqui!",
  ui_story_5058_50580101_74_dialog_content = "Espero que sim.",
  ui_story_5058_50580101_75_dialog_content = "Ei, Carleen, não me olhe assim! Nada vai dar errado desta vez, não é? Ei!",
  ui_story_5058_50580101_76_dialog_content = "<color=#828282>Crec...</color>",
  ui_story_5058_50580101_77_dialog_content = "Chegamos, pessoal. Por favor, saiam do veículo.",
  ui_story_5058_50580101_78_dialog_content = "Hum... era... era essa a sua \"ótima direção\" mencionada anteriormente?",
  ui_story_5058_50580101_79_dialog_content = "La-la-la, la-ta-ta-la-la... ♪",
  ui_story_5058_50580101_80_dialog_content = "O que foi?",
  ui_story_5058_50580101_81_dialog_content = "La-la-la, la-ta-ta-la-la ♪ O Resort Vale Denuo te dá as boas-vindas ♪",
  ui_story_5058_50580101_82_dialog_content = "Uau, é igualzinho à imagem do folheto!",
  ui_story_5058_50580101_83_dialog_content = "Estávamos apenas em um deserto árido e agora está tão vibrante ao redor... É como se estivéssemos em um mundo diferente.",
  ui_story_5058_50580101_84_dialog_content = "Muito obrigado a todos vocês, pessoas incríveis, por escolherem o Denuo Valley Resort para começar suas férias fantásticas! Preparem-se para diversão sem parar e aventuras épicas!",
  ui_story_5058_50580101_85_dialog_content = "Sim, exatamente, diversão sem parar e aventuras épicas! Mas isso ainda parece tão básico!",
  ui_story_5058_50580101_86_dialog_content = "\"Além disso, ofereceremos os serviços mais sofisticados e banquetes suntuosos?\"",
  ui_story_5058_50580101_87_dialog_content = "Hmm. Cena, lembre o pessoal da publicidade para trabalhar no slogan da entrada.",
  ui_story_5058_50580101_88_dialog_content = "Entendi, Senhorita Lorelei.",
  ui_story_5058_50580101_89_dialog_content = "Senhorita Lorelei? Então você é a Senhorita Lorelei Cardogon, a proprietária?",
  ui_story_5058_50580101_90_dialog_content = "<size=45>PlayerName, você finalmente chegou!</size>",
  ui_story_5058_50580101_91_dialog_content = "Uau, que rabo adorável! Você deve ser o Vice.",
  ui_story_5058_50580101_92_dialog_content = "E a jovem etérea aqui deve ser Carleen!",
  ui_story_5058_50580101_93_dialog_content = "Fico feliz por ter tido a previsão de incluir três passes. Eu tinha uma intuição de que você traria os dois, PlayerName!",
  ui_story_5058_50580101_94_dialog_content = "Sou grato por você tirar um tempo da sua agenda corrida para participar da nossa pré-inauguração.",
  ui_story_5058_50580101_95_dialog_content = "Por favor, sintam-se em casa. Aproveitem e divirtam-se à vontade!",
  ui_story_5058_50580101_96_dialog_content = "Bem, obrigado por nos convidar, Srta. Lorelei. Eu nunca estive em um parque tão magnífico como este!",
  ui_story_5058_50580101_97_dialog_content = "Por favor, apenas me chame de Lorelei.",
  ui_story_5058_50580101_98_dialog_content = "Hmm, a Teeny deveria te mostrar tudo... Cadê ela?",
  ui_story_5058_50580101_99_dialog_content = "De qualquer forma, por favor entre!",
  ui_story_5058_50580101_100_dialog_content = "...",
  ui_story_5058_50580101_101_dialog_content = "Ei, aquela garota ruiva bem ali...",
  ui_story_5058_50580101_102_option_content = "Acho que eu a conheço!",
  ui_story_5058_50580101_103_dialog_content = "Não é esse Bopper?",
  ui_story_5058_50580101_104_dialog_content = "PlayerName... É claro. Ninguém além de você me notaria logo de cara...",
  ui_story_5058_50580101_105_option_content = "Ela parece familiar.",
  ui_story_5058_50580101_106_dialog_content = "Sabia... Acho que faz muito tempo para você se lembrar de mim.",
  ui_story_5058_50580101_107_dialog_content = "Eu sou Bopper, PlayerName. Você tem o passarinho gigante e eu tenho meu Lagarto Gigante!",
  ui_story_5058_50580101_108_dialog_content = "Bopper, da Chave Rediesel?!",
  ui_story_5058_50580101_109_dialog_content = "Aí está você, Pequenino. Eu estive procurando muito por você!",
  ui_story_5058_50580101_110_dialog_content = "Mas eu estive ao seu lado o tempo todo, Srta. Lorelei...",
  ui_story_5058_50580101_111_dialog_content = "Você também está aqui para a pré-inauguração, Bopper?",
  ui_story_5058_50580101_112_dialog_content = "Ela é a especialista técnica que eu solicitei especificamente da Rediesel Wrench!",
  ui_story_5058_50580101_113_dialog_content = "Bem, na verdade eu sou mais um mecânico geral do que o especialista que a Srta. Lorelei me faz parecer... Outros caras da Rediesel Wrench também estão aqui para ajudar.",
  ui_story_5058_50580101_114_dialog_content = "As pessoas da Chave Rediesel estão trabalhando em empregos regulares agora? Essa pode ser minha chance de capturar alguns desses fugitivos procurados.",
  ui_story_5058_50580101_115_dialog_content = "Ah, Carleen, vamos não pensar nisso nas nossas férias, tá bom?",
  ui_story_5058_50580101_116_dialog_content = "Nossos funcionários do resort passaram por verificações de antecedentes e treinamentos extensivos. Nós cuidaremos de quaisquer problemas que possam surgir sem que você precise levantar um dedo.",
  ui_story_5058_50580101_117_dialog_content = "Desculpe interromper, senhor. Três clientes lá fora estão pedindo especificamente para vê-lo...",
  ui_story_5058_50580101_118_dialog_content = "Acredito que terminei aqui, Srta. Lorelei. Vou cuidar de outros negócios.",
  ui_story_5058_50580101_119_dialog_content = "PlayerName, Srta. Vice e Srta. Carleen, desejo a todos vocês uma estadia divertida antecipadamente!",
  ui_story_5058_50580101_120_dialog_content = "Não me diga que outro grupo de belas senhoras acabou de aparecer? Eu simplesmente não sei o que fazer com ele...",
  ui_story_5058_50580101_121_dialog_content = "Embora eu não consiga acreditar no horário... Por que a reunião teve que ser marcada para agora?",
  ui_story_5058_50580101_122_dialog_content = "Bem, pessoal, estou feliz em ter todos vocês aqui!",
  ui_story_5058_50580101_123_dialog_content = "Mas preciso ir agora. Quando terminar, farei seu check-in no hotel e mostrarei as atrações!",
  ui_story_5058_50580101_124_dialog_content = "Você pode continuar daqui, Teeny!",
  ui_story_5058_50580101_125_dialog_content = "Aham... pode me chamar de Bopper...",
  ui_story_5058_50580101_126_dialog_content = "Sabendo que você estava chegando, fiquei acordado a noite toda e elaborei trinta e três roteiros.",
  ui_story_5058_50580101_127_dialog_content = "Eu combinei as preferências pessoais de PlayerName, Vice e Carleen para obter os melhores passos e rota...",
  ui_story_5058_50580101_128_dialog_content = "Ah, você não precisa ser tão minucioso, Bopper. Podemos apenas relaxar.",
  ui_story_5058_50580101_129_dialog_content = "Ficar tranquilo? Felizmente, eu também tenho um plano para isso.",
  ui_story_5058_50580101_130_dialog_content = "Tudo bem, então. Sigam-me, todos.",
  ui_story_5058_50580101_131_dialog_content = "Estamos prestes a embarcar no roteiro mais casual planejado!",
  ui_story_5058_50580201_1_dialog_content = "Estas são as fotos PlayerName que o Caelestite tirou no caminho para o resort.",
  ui_story_5058_50580201_2_dialog_content = "Também vamos fotografar o Caelestite com as várias atrações e comodidades do hotel.",
  ui_story_5058_50580201_3_dialog_content = "Então podemos colocar um artigo completo na sua publicação!",
  ui_story_5058_50580201_4_dialog_content = "Isso irá vender a questão e aumentar a exposição para o resort.",
  ui_story_5058_50580201_5_dialog_content = "Hmm... Tenho que admitir que os Lovegators realmente têm algum poder de compra.",
  ui_story_5058_50580201_6_dialog_content = "Com base em nossas descobertas, lugares que o Caelestite visita tendem a se tornar virais, como Ilha das Nuvens, Cidade do Porto...",
  ui_story_5058_50580201_7_dialog_content = "EveEm um lugar como Euforia floresceu!",
  ui_story_5058_50580201_8_dialog_content = "Verdadeiro, a Cidade do Porto é agora o destino turístico mais popular em Astra.",
  ui_story_5058_50580201_9_dialog_content = "Cidade do Porto? Por que isso me parece familiar?",
  ui_story_5058_50580201_10_dialog_content = "Você, em uma missão, decidiu entrar em uma competição no meio do caminho e quase acabou caindo na água.",
  ui_story_5058_50580201_11_dialog_content = "AHHH! Memórias daqueles plebeus imprudentes correndo por aí voltam à tona! Cale a boca! CALE A BOCA!",
  ui_story_5058_50580201_12_dialog_content = "Lorelei, estou feliz que você seguiu nosso conselho e usou a Deusa Denuo como o grande avanço na divulgação do resort.",
  ui_story_5058_50580201_13_dialog_content = "E eu realmente aprecio sua ideia de aproveitar a fama do Caelestite para promoção.",
  ui_story_5058_50580201_14_dialog_content = "Mas sinceramente, essas são todas estratégias temporárias de marketing e talvez não se sustentem a longo prazo.",
  ui_story_5058_50580201_15_dialog_content = "Todos nós sabemos que a Deusa Denuo é apenas uma história. Quem sabe se ela realmente existe?",
  ui_story_5058_50580201_16_dialog_content = "Sem mencionar que a popularidade do Caelestite pode não durar e, algum dia, pode se transformar em uma grande dor de cabeça.",
  ui_story_5058_50580201_17_dialog_content = "O dinheiro que investimos no resort não é uma quantia insignificante...",
  ui_story_5058_50580201_18_dialog_content = "Entendo o que todos vocês querem como investidores.",
  ui_story_5058_50580201_19_dialog_content = "Para tornar o resort uma operação sustentável, devemos garantir serviços de qualidade e fornecer—",
  ui_story_5058_50580201_20_dialog_content = "Não, o que eu quero dizer é que devemos oferecer algo mais \"viciante\"...",
  ui_story_5058_50580201_21_dialog_content = "...",
  ui_story_5058_50580201_22_dialog_content = "Você tem certeza de que este é o seu roteiro mais casual, Bopper?",
  ui_story_5058_50580201_23_dialog_content = "Sim... Essa é a rota que eu faço quando quero relaxar, eu mesmo.",
  ui_story_5058_50580201_24_dialog_content = "Isso realmente te relaxa?!",
  ui_story_5058_50580201_25_dialog_content = "A Porta da Morte é o meu brinquedo favorito. Algumas pessoas em Rediesel Wrench poderiam andar nele uma dúzia de vezes por dia!",
  ui_story_5058_50580201_26_dialog_content = "Temos sorte de você ter chegado cedo. Caso contrário, teríamos que esperar em uma longa fila.",
  ui_story_5058_50580201_27_dialog_content = "Uau, mal posso esperar! Anda logo, PlayerName.",
  ui_story_5058_50580201_28_dialog_content = "Acho que meus joelhos já estão dobrando...",
  ui_story_5058_50580201_29_dialog_content = "O quê? Eu pensei que você estaria acostumado com essa altura, já que pilota a Águia Gigante com frequência...",
  ui_story_5058_50580201_30_dialog_content = "Ela tem razão. Você já passou por várias quedas, então isso deveria ser brincadeira de criança agora.",
  ui_story_5058_50580201_31_dialog_content = "Fazer algo assim ativamente em comparação a não ter escolha é completamente diferente...",
  ui_story_5058_50580201_32_dialog_content = "Relaxe, acho que você vai ficar bem!",
  ui_story_5058_50580201_33_dialog_content = "Nesse caso, eu acho que o PlayerName deve enfrentar o desafio mais difícil!",
  ui_story_5058_50580201_34_dialog_content = "Depois que você pular, bonecas infláveis Eclipsita serão liberadas ao seu redor.",
  ui_story_5058_50580201_35_dialog_content = "Pegue-os a caminho da descida para ganhar adesivos comemorativos.",
  ui_story_5058_50580201_36_dialog_content = "E, você também pode levar as Eclipsitas infláveis para casa!",
  ui_story_5058_50580201_37_dialog_content = "Quem iria querer bonecas infláveis que se parecem com Eclipsites?!",
  ui_story_5058_50580201_38_dialog_content = "Eu, eu, eu gostaria!",
  ui_story_5058_50580201_39_dialog_content = "Por favor, traga um de volta para mim!",
  ui_story_5058_50580201_40_dialog_content = "O quê?",
  ui_story_5058_50580201_41_dialog_content = "Ahrrrgggh—!",
  ui_story_5058_50580201_42_dialog_content = "Você poderia ter me dado um aviso, pelo menos!",
  ui_story_5058_50580202_1_dialog_content = "Tudo bem? Você continua esfregando seus olhos... está chorando?",
  ui_story_5058_50580202_2_dialog_content = "Não, não é isso!",
  ui_story_5058_50580202_3_dialog_content = "Havia todas essas luzes piscando nos meus olhos durante a queda...",
  ui_story_5058_50580202_4_dialog_content = "Ah, era uma câmera tirando fotos. Quer ver as fotos?",
  ui_story_5058_50580202_5_dialog_content = "Esquece, eu provavelmente pareço estranho...",
  ui_story_5058_50580202_6_dialog_content = "Confira todos os adesivos que eu consegui!",
  ui_story_5058_50580202_7_dialog_content = "Hã? Vocês dois conseguiram? Parabéns por passar pelo jogo!",
  ui_story_5058_50580202_8_dialog_content = "EveCada atração no parque tem desafios e você ganha adesivos ao completá-los.",
  ui_story_5058_50580202_9_dialog_content = "Quanto mais adesivos você conseguir, melhores serão os prêmios que você pode resgatar.",
  ui_story_5058_50580202_10_dialog_content = "Ei, Carleen, quer ver quem ganha o melhor prêmio?",
  ui_story_5058_50580202_11_dialog_content = "Claro, mas não peça ajuda ao PlayerName para te ajudar.",
  ui_story_5058_50580202_12_dialog_content = "Seria um milagre se eu não precisasse ajudar o PlayerName, quanto mais o contrário.",
  ui_story_5058_50580202_13_dialog_content = "Ei, eu posso te ouvir, viu.",
  ui_story_5058_50580202_14_dialog_content = "Nossa, a borboleta neste adesivo está realmente linda!",
  ui_story_5058_50580202_15_dialog_content = "Isso não é uma borboleta comum, mas sim a Deusa Denuo única do Vale Denuo.",
  ui_story_5058_50580202_16_dialog_content = "A Deusa Denuo realmente existe?",
  ui_story_5058_50580202_17_dialog_content = "Acredito que sim! Alguém acabou de dizer que encontrou isso no resort recentemente...",
  ui_story_5058_50580202_18_dialog_content = "E muitos turistas gastaram um bom dinheiro na nossa pré-inauguração apenas pela chance de vê-lo antes de todos os outros.",
  ui_story_5058_50580202_19_dialog_content = "Graças a PlayerName, não precisamos gastar nada! Mas eu me pergunto se conseguiremos dar uma olhada desta vez...",
  ui_story_5058_50580202_20_dialog_content = "Se é real, por que não mostrar ao público?",
  ui_story_5058_50580202_21_dialog_content = "Todo esse alarde apenas para deixar ao acaso... Isso me parece um golpe.",
  ui_story_5058_50580202_22_dialog_content = "Nossa, você deve ser o Caelestite que Cena mencionou. Eu poderia te reconhecer a um quilômetro de distância na multidão!",
  ui_story_5058_50580202_23_dialog_content = "Por que você está esfregando os olhos? Eles estão doendo ou algo assim?",
  ui_story_5058_50580202_24_dialog_content = "Pois é...",
  ui_story_5058_50580202_25_dialog_content = "Parece que é sua primeira vez tentando pular de bungee jump.",
  ui_story_5058_50580202_26_dialog_content = "A primeira vez pode ser um pouco desconfortável. As pessoas ao seu lado são sua família ou amigos? Por que eles parecem tão indiferentes?",
  ui_story_5058_50580202_27_dialog_content = "Coitado. Bem, já que eles não estão preocupados com você... vamos te dar uma massagem relaxante e ajudar você a relaxar.",
  ui_story_5058_50580202_28_dialog_content = "T-Tudo bem, valeu...",
  ui_story_5058_50580202_29_dialog_content = "Apenas relaxe! Nossas habilidades de massagem são de primeira linha.",
  ui_story_5058_50580202_30_dialog_content = "V-Vice, Carleen... Algum de vocês...",
  ui_story_5058_50580202_31_dialog_content = "Eu estava me perguntando para onde as senhoras foram. Você não pode simplesmente monopolizá-las para si mesmo, PlayerName!",
  ui_story_5058_50580202_32_dialog_content = "E aí, gracinha? Está com ciúmes?",
  ui_story_5058_50580202_33_dialog_content = "Suspiro, nunca pensei que haveria um dia em que eu ficaria em segundo lugar.",
  ui_story_5058_50580202_34_dialog_content = "Vamos lá, quando você começou a agir tão possessivo? Aqui, deixe-me te dar uma massagem também, tudo bem?",
  ui_story_5058_50580202_35_dialog_content = "Eu sabia que eu era o favorito(a) de Lina...",
  ui_story_5058_50580202_36_dialog_content = "S-Salve-me, Cena...",
  ui_story_5058_50580202_37_dialog_content = "O que é isso, PlayerName? Você vai fazer as senhoras se sentirem mal.",
  ui_story_5058_50580202_38_dialog_content = "Do que você está falando? Eu nem sei quem são eles!",
  ui_story_5058_50580202_39_dialog_content = "Você só quer saber os nomes deles. Hahaha, eu deveria te ajudar.",
  ui_story_5058_50580202_40_dialog_content = "Conheci todas as três senhoras em viagens anteriores. Todas elas adoram viajar.",
  ui_story_5058_50580202_41_dialog_content = "Não se deixe enganar pelas aparências. Eles são muito exigentes quando se trata de viagens.",
  ui_story_5058_50580202_42_dialog_content = "É por isso que eu os convidei especificamente para o resort como consultores.",
  ui_story_5058_50580202_43_dialog_content = "A senhora de turbante é Winona. Passamos muito tempo juntos no Northland explorando ruínas antigas. Somos unidos como nunca.",
  ui_story_5058_50580202_44_dialog_content = "Winona atua como nosso consultor de segurança.",
  ui_story_5058_50580202_45_dialog_content = "Muito prazer.",
  ui_story_5058_50580202_46_dialog_content = "A massagista com as mãos maravilhosas é Lastelle. Eu a escoltei antes quando trabalhava como segurança secreta em Lumópolis.",
  ui_story_5058_50580202_47_dialog_content = "Lastelle é um consultor de hospitalidade especializado em relaxamento. Além disso—",
  ui_story_5058_50580202_48_dialog_content = "Tudo bem, isso é o suficiente. Não conte tudo, meu bem. Isso só vai tirar o elemento surpresa.",
  ui_story_5058_50580202_49_dialog_content = "Quando eu era um limpador na área rural de Umbraton, salvei Lina de trinta assassinos. Ela é nossa consultora gourmet.",
  ui_story_5058_50580202_50_dialog_content = "Não faço ideia de por que tantas pessoas tentariam matar Lina. Ela é claramente a mulher mais gentil e amável que já conheci.",
  ui_story_5058_50580202_51_dialog_content = "Hee-hee... Cena, você nunca deixa de impressionar com suas palavras suaves, não é?",
  ui_story_5058_50580202_52_dialog_content = "Não fique aí parado! Agora que você está aqui, vamos à parte divertida!",
  ui_story_5058_50580202_53_dialog_content = "Você tem razão. Depois de toda essa conversa, devemos conferir as atrações!",
  ui_story_5058_50580202_54_dialog_content = "Por que não vamos para algo mais discreto... Como a roda-gigante ali?",
  ui_story_5058_50580202_55_dialog_content = "Mas... Eu deixei a roda-gigante por último no roteiro.",
  ui_story_5058_50580202_56_dialog_content = "A vista de lá é ainda melhor à noite por causa dos fogos de artifício noturnos!",
  ui_story_5058_50580202_57_dialog_content = "Fogos de artifício do topo da roda-gigante? Que romântico!",
  ui_story_5058_50580202_58_dialog_content = "Fogos de artifício, hein...",
  ui_story_5058_50580202_59_dialog_content = "O que há de errado, Cena? Você não gosta de shows de fogos de artifício?",
  ui_story_5058_50580202_60_dialog_content = "Não... Eu, ah, só...",
  ui_story_5058_50580202_61_dialog_content = "Acabei de pensar em um lugar muito especial em mente que gostaria de levar as senhoras.",
  ui_story_5058_50580202_62_dialog_content = "Espero que você não me decepcione então.",
  ui_story_5058_50580202_63_dialog_content = "Claro que não. Sigam-me, minhas lindas senhoras!",
  ui_story_5058_50580202_64_dialog_content = "E-Ele está indo embora, assim mesmo?",
  ui_story_5058_50580202_65_dialog_content = "Está bem. Cena pode dizer coisas inadequadas, mas ele ainda é uma pessoa confiável!",
  ui_story_5058_50580202_66_dialog_content = "Ele ajudou a Lorelei restaurar a ecologia no Vale Denuo para o lançamento do resort.",
  ui_story_5058_50580202_67_dialog_content = "Restaurar a ecologia?",
  ui_story_5058_50580202_68_dialog_content = "Não faz muito tempo, o Vale Denuo ainda era árido.",
  ui_story_5058_50580202_69_dialog_content = "Mas Lorelei se concentrou no terreno, investiu uma enorme quantia para melhorar o ambiente e o restaurou ao que costumava ser.",
  ui_story_5058_50580202_70_dialog_content = "Isso parece muito trabalho.",
  ui_story_5058_50580202_71_dialog_content = "E Cena sempre conseguia encontrar uma solução para completar qualquer uma das exigências aparentemente loucas de Lorelei.",
  ui_story_5058_50580202_72_dialog_content = "Even Sinsa gostou dele o suficiente para tentar recrutá-lo...",
  ui_story_5058_50580202_73_dialog_content = "O Sinsa não diz isso para qualquer pessoa que ele encontra?",
  ui_story_5058_50580202_74_dialog_content = "Mas mesmo assim... Tá bom, talvez eu nunca deva julgar um livro pela capa.",
  ui_story_5058_50580202_75_dialog_content = "<color=#e8d9bb>Espalhando—</color>",
  ui_story_5058_50580202_76_dialog_content = "Então, é este o lugar especial que você estava falando?",
  ui_story_5058_50580202_77_dialog_content = "Sim. Vocês senhoras não preferem nadar e tomar sol em algum lugar tranquilo?",
  ui_story_5058_50580202_78_dialog_content = "A maioria dos convidados está no parque de diversões, então quase ninguém está aqui na Piscina Oásis. Sinta-se à vontade para se divertir.",
  ui_story_5058_50580202_79_dialog_content = "Cena, por que você não vem nadar conosco também?",
  ui_story_5058_50580202_80_dialog_content = "Obrigado, mas receio que tenho que sair por enquanto.",
  ui_story_5058_50580202_81_dialog_content = "A reunião da Srta. Lorelei está quase terminando. Eu preciso ir descobrir o que saiu dela.",
  ui_story_5058_50580202_82_dialog_content = "Nossa. Cena, quando você começou a gostar de garotas mais jovens?",
  ui_story_5058_50580202_83_dialog_content = "Eu entenderia se viesse de outra pessoa, mas não me diga que você ainda não conhece o meu gosto?",
  ui_story_5058_50580202_84_dialog_content = "Sou apenas um funcionário que quer manter o chefe feliz para que eu possa ganhar muito dinheiro e te mimar!",
  ui_story_5058_50580202_85_dialog_content = "Sério?",
  ui_story_5058_50580202_86_dialog_content = "Cena, obviamente tem algo em sua mente que você não quer compartilhar conosco.",
  ui_story_5058_50580202_87_dialog_content = "Bem, sempre que você quiser, pode vir até nós e conversar, tá bom?",
  ui_story_5058_50580202_88_dialog_content = "Claro. Divirtam-se e aproveitem, senhoras. Claro, não economizem nas críticas e sugestões!",
  ui_story_5058_50580301_1_dialog_content = "Ei, isso é raro, não te vejo tão infeliz há muito tempo.",
  ui_story_5058_50580301_2_dialog_content = "O que os investidores disseram na reunião do conselho?",
  ui_story_5058_50580301_3_dialog_content = "Você já ouviu falar do <color=#FFB400>Incenso Denuo</color>?",
  ui_story_5058_50580301_4_dialog_content = "Incenso Denuo...",
  ui_story_5058_50580301_5_dialog_content = "Hmm, não posso dizer que já fiz isso antes.",
  ui_story_5058_50580301_6_dialog_content = "Então você também não sabe sobre isso? O Conselho disse que é uma especiaria especial em Denuo e já foi uma grande moda uma vez.",
  ui_story_5058_50580301_7_dialog_content = "Eles querem que a gente produza e promova até a lua como o produto estrela do resort, assim teremos clientes que retornam.",
  ui_story_5058_50580301_8_dialog_content = "Uau, isso vai ser difícil... O que você disse a eles?",
  ui_story_5058_50580301_9_dialog_content = "Vou levar isso em consideração. Você mesmo sabe como eles têm me pressionado para expandir o resort e desenvolver mais o vale na fase dois.",
  ui_story_5058_50580301_10_dialog_content = "Mas eles me prometeram que, se fabricarmos o Incenso Denuo, eles vão parar de interferir nos desenvolvimentos futuros.",
  ui_story_5058_50580301_11_dialog_content = "Isso parece muito tentador, considerando as restrições e condições que exigiram quando começamos o projeto.",
  ui_story_5058_50580301_12_dialog_content = "No entanto, eles também não ofereceram ajuda sobre como proceder para fazer o incenso.",
  ui_story_5058_50580301_13_dialog_content = "Falando nisso, a Vila Denuo negociou com o mundo exterior por um tempo. Maytalvez alguém lá tenha conseguido.",
  ui_story_5058_50580301_14_dialog_content = "Mas a vila já desapareceu há muito tempo. Como vamos encontrar a fórmula?",
  ui_story_5058_50580301_15_dialog_content = "Verdade...",
  ui_story_5058_50580301_16_dialog_content = "Não se preocupe, eu também me aventuro em temperos. May Posso tentar.",
  ui_story_5058_50580301_17_dialog_content = "Você até sabe sobre especiarias? O que o resort vai fazer sem você!",
  ui_story_5058_50580301_18_dialog_content = "Haha, espero que eu possa tirar um coelho da cartola.",
  ui_story_5058_50580301_19_dialog_content = "Por favor! Even mesmo que não seja totalmente perfeito, ainda beneficiará o vale.",
  ui_story_5058_50580301_20_dialog_content = "Não podemos abandonar nosso plano de marketing original, no entanto. O Caelestite ainda é o foco.",
  ui_story_5058_50580301_21_dialog_content = "O quê, você não ganhou nenhum adesivo da Deusa Denuo na noite clara dos Dragões?",
  ui_story_5058_50580301_22_dialog_content = "...",
  ui_story_5058_50580301_23_dialog_content = "Carleen parece meio pálido... Montanhas-russas são demais para você?",
  ui_story_5058_50580301_24_dialog_content = "Como é possível que alguém consiga encarar um salto de bungee, mas não uma montanha-russa?",
  ui_story_5058_50580301_25_dialog_content = "Mayparece que há um problema com o itinerário. Eu deveria ter separado as categorias...",
  ui_story_5058_50580301_26_dialog_content = "Mas a Matriz Fantasia que vem a seguir deve oferecer um suspense totalmente diferente!",
  ui_story_5058_50580301_27_dialog_content = "Matrix Fantasia? Finalmente, parece um passeio simples e fácil. Onde fica?",
  ui_story_5058_50580301_28_dialog_content = "Aí está! Bem na nossa frente. Olhe para cima, PlayerName!",
  ui_story_5058_50580301_29_dialog_content = "Olhe para cima...?",
  ui_story_5058_50580301_30_dialog_content = "Caramba... Parece uma serra gigante! Isso é uma carona? Tem certeza?",
  ui_story_5058_50580301_31_dialog_content = "É, Sinsa projetou isso, e como ele costumava dizer...",
  ui_story_5058_50580301_32_dialog_content = "Tudo bem, seus arruaceiros, será a serra elétrica para vocês se não forem rápidos o suficiente para desviar!",
  ui_story_5058_50580301_33_dialog_content = "Eve? Não, isso não se aplica a você, Eve...!",
  ui_story_5058_50580301_34_dialog_content = "É, isso é algo que ele diria.",
  ui_story_5058_50580301_35_dialog_content = "Isso é brincadeira de criança. Vejo que são mais adesivos para mim.",
  ui_story_5058_50580301_36_dialog_content = "Esse é o Carleen que eu conheço. Ok, vamos lá, eu não posso esperar!",
  ui_story_5058_50580301_37_dialog_content = "Então, antes de começarmos, não se esqueça das medidas de segurança!",
  ui_story_5058_50580301_38_dialog_content = "<color=#e8d9bb>Zumbindo—</color>",
  ui_story_5058_50580301_39_dialog_content = "Anda logo, Carleen, senão vou te vencer!",
  ui_story_5058_50580301_40_dialog_content = "Eu já estou pronto. Você só precisa tomar cuidado!",
  ui_story_5058_50580301_41_dialog_content = "Ei, me espera... Por que estou sendo deixado para trás de novo?",
  ui_story_5058_50580301_42_dialog_content = "Ei, pessoal—",
  ui_story_5058_50580301_43_dialog_content = "Todos eles correram... Acho que vou apenas vagar sozinho.",
  ui_story_5058_50580301_44_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5058_50580301_45_dialog_content = "Parabéns ao melhor atirador da partida: Senhorita Smokey!",
  ui_story_5058_50580301_46_dialog_content = "Parabéns, você acabou de ganhar outro adesivo da Deusa Denuo, 'ol grande Diretor Smokey!",
  ui_story_5058_50580301_47_dialog_content = "Você me deixou dar os dois últimos tiros, não foi, <color=#FFB400>Shashona</color>?",
  ui_story_5058_50580301_48_dialog_content = "O que? De jeito nenhum! Você é um jovem atirador habilidoso, Diretor Smokey. Eu só dei uma disfarçada.",
  ui_story_5058_50580301_49_dialog_content = "Assim como você provavelmente pode dar uma disfarçada também no Conselho de Administração.",
  ui_story_5058_50580301_50_dialog_content = "Ah, entendi do que se trata.",
  ui_story_5058_50580301_51_dialog_content = "Bem, o Conselho está pressionando o Lorelei para expandir o projeto.",
  ui_story_5058_50580301_52_dialog_content = "Mas como todo empresário sabe, a pressa é inimiga da perfeição.",
  ui_story_5058_50580301_53_dialog_content = "Por que não podemos simplesmente construir a marca do resort e depois reinvestir o dinheiro em mais projetos?",
  ui_story_5058_50580301_54_dialog_content = "Eu praticamente não tenho interesse em administrar um negócio ou ouvir suas sugestões.",
  ui_story_5058_50580301_55_dialog_content = "Contanto que os passeios sejam emocionantes e divertidos para mim, eu não me importo com o resto.",
  ui_story_5058_50580301_56_dialog_content = "Falando nisso, todas as atrações não são desafiadoras o suficiente. Certifique-se de avisar o Lorelei...",
  ui_story_5058_50580301_57_dialog_content = "Torne tudo mais difícil e adicione mais truques de pontuação. Nem todos precisam ser atirando em grandes Eclipsitas como Halo Shots. Isso é chato.",
  ui_story_5058_50580301_58_dialog_content = "Você acha? Eu achei divertido jogar com você. Outra rodada?",
  ui_story_5058_50580301_59_dialog_content = "Alvo à vista—",
  ui_story_5058_50580301_60_dialog_content = "Qual alvo? Eu?",
  ui_story_5058_50580301_61_dialog_content = "O que está fazendo aqui?",
  ui_story_5058_50580301_62_dialog_content = "Recebi um convite de Lorelei para a pré-inauguração. Você também recebeu um?",
  ui_story_5058_50580301_63_dialog_content = "Ao contrário de você, sou diretor do resort, aqui para avaliar o progresso.",
  ui_story_5058_50580301_64_dialog_content = "Você é... um membro do Conselho de Administração?",
  ui_story_5058_50580301_65_dialog_content = "Por que isso é uma surpresa? Claro, eu nunca fiz isso, mas achei que seria interessante investir em um resort.",
  ui_story_5058_50580301_66_dialog_content = "E eu ganhei no cassino recentemente com dinheiro queimando um buraco no meu bolso, então é melhor gastá-lo.",
  ui_story_5058_50580301_67_dialog_content = "Parece realmente bom ser rico...",
  ui_story_5058_50580301_68_dialog_content = "Você é... o Celestita? Estou impressionado que Lorelei conseguiu trazer você aqui.",
  ui_story_5058_50580301_69_dialog_content = "Ah, você é muito gentil. Apenas me chame de PlayerName.",
  ui_story_5058_50580301_70_dialog_content = "Legal! Prazer em conhecer você, PlayerName, eu sou Shashona.",
  ui_story_5058_50580301_71_dialog_content = "Divirta-se! Vamos conversar novamente depois que você tiver ido em todos os brinquedos.",
  ui_story_5058_50580301_72_dialog_content = "A diretoria deve estar muito interessada nos comentários de PlayerName, não é?",
  ui_story_5058_50580301_73_dialog_content = "Ei, você já experimentou o Fantasy Matrix? Parece ser divertido.",
  ui_story_5058_50580301_74_dialog_content = "Por que todos querem isso? Eu prefiro tentar algo diferente.",
  ui_story_5058_50580301_75_dialog_content = "Bem então, experimente isso. Não é difícil e deve ser fácil para você.",
  ui_story_5058_50580301_76_dialog_content = "Apenas aponte a arma para os Eclipsitas e atire.",
  ui_story_5058_50580301_77_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5058_50580301_78_dialog_content = "Uau, já está começando? Aliás, os Eclipsitas são tão reais quanto possível!",
  ui_story_5058_50580301_79_dialog_content = "Este é um concurso. Se você ganhar, poderá andar na Matriz Fantasia comigo!",
  ui_story_5058_50580301_80_dialog_content = "Não, tudo bem, tudo o que eu quero são adesivos...",
  ui_story_5058_50580402_1_dialog_content = "Ei, você me impressionou desde a última vez que te vi! Embora você não esteja no meu nível.",
  ui_story_5058_50580402_2_dialog_content = "Ah, tenho certeza de que pouquíssimas pessoas conseguiriam atirar melhor que você.",
  ui_story_5058_50580402_3_dialog_content = "Eu brinquei com quase tudo e consegui todos os adesivos... O que falta fazer?",
  ui_story_5058_50580402_4_dialog_content = "Há muitas comodidades de hotel que vale a pena experimentar. Que tal receber uma massagem com óleo?",
  ui_story_5058_50580402_5_dialog_content = "Eu enviei Lorelei para implorar ao mestre no local mais renomado para criar a essência personalizada para o resort. Você não encontra isso em nenhum outro lugar.",
  ui_story_5058_50580402_6_dialog_content = "Claro, vou verificar. Até mais tarde.",
  ui_story_5058_50580402_7_dialog_content = "Você também estaria interessado, velho amigo de Smokey?",
  ui_story_5058_50580402_8_dialog_content = "Bem, somos amigos, mas provavelmente não tão próximos para fazer uma massagem juntos...",
  ui_story_5058_50580402_9_dialog_content = "Heheh, não tem problema. Amigos frequentemente vão à banheira de hidromassagem, quanto mais massagem.",
  ui_story_5058_50580402_10_dialog_content = "Mayvocê pode até discutir possíveis colaborações...",
  ui_story_5058_50580402_11_dialog_content = "Uau, você ainda tem negócios em mente no seu centro... Muito mais diretor do que Smokey.",
  ui_story_5058_50580402_12_dialog_content = "Obrigado pelo elogio, mas não sou diretor, apenas um parente do Lorelei, para dar uma mãozinha.",
  ui_story_5058_50580402_13_dialog_content = "Parente de Lorelei, entendo...",
  ui_story_5058_50580402_14_dialog_content = "PlayerName!",
  ui_story_5058_50580402_15_dialog_content = "Aqui está você! Ninguém conseguia te encontrar e estávamos preocupados...",
  ui_story_5058_50580402_16_dialog_content = "Ah, perdão. Quando você estava entrando na Matriz Fantasia, eu...",
  ui_story_5058_50580402_17_dialog_content = "... O que está fazendo aqui?",
  ui_story_5058_50580402_18_dialog_content = "Ah, Laurie, como você não me disse que o resort está aberto?",
  ui_story_5058_50580402_19_dialog_content = "A quantidade de convidados parece baixa para uma operação dessa escala.",
  ui_story_5058_50580402_20_dialog_content = "É apenas uma pré-inauguração antes da verdadeira grande inauguração. EveTodos aqui são convidados exclusivos.",
  ui_story_5058_50580402_21_dialog_content = "Ah, então eu acertei que esse cara está aqui para promover o parque?",
  ui_story_5058_50580402_22_dialog_content = "Você ganha um passe por tornar o Caelestite o porta-voz do parque.",
  ui_story_5058_50580402_23_dialog_content = "Mas se você tivesse me dito antes, eu teria vindo mais cedo e pessoalmente mostrado PlayerName por aí, para que não houvesse nenhuma pessoa solitária...",
  ui_story_5058_50580402_24_dialog_content = "Eu sabia que você faria isso, foi por isso que—",
  ui_story_5058_50580402_25_dialog_content = "Olhe para a sua pele, você deve não estar hidratado adequadamente.",
  ui_story_5058_50580402_26_dialog_content = "Trouxe alguns suplementos de casa. Vou cozinhá-los para você esta noite.",
  ui_story_5058_50580402_27_dialog_content = "Mãe, por favor, não fale sobre isso na frente de um convidado. Eu sou velho o suficiente para me cuidar.",
  ui_story_5058_50580402_28_dialog_content = "(O-O quê? Shashona é a mãe de Lorelei?!)",
  ui_story_5058_50580402_29_dialog_content = "De qualquer forma, preciso sair e levar nosso convidado aqui para fazer o check-in.",
  ui_story_5058_50580402_30_dialog_content = "Por aqui, por favor, PlayerName.",
  ui_story_5058_50580402_31_dialog_content = "Acalme-se, Laurie. Por que você não está usando os sapatos que eu comprei para você? Aquele par não é para o trabalho...",
  ui_story_5058_50580402_32_dialog_content = "Ufa...",
  ui_story_5058_50580402_33_dialog_content = "Sua mãe é muito boa para você, Lorelei.",
  ui_story_5058_50580402_34_dialog_content = "Ela certamente é.",
  ui_story_5058_50580501_1_dialog_content = "Tudo bem, você está todo registrado.",
  ui_story_5058_50580501_2_dialog_content = "Obrigado, Lorelei.",
  ui_story_5058_50580501_3_dialog_content = "Parte do meu trabalho, e verdade seja dita, eu deveria fazer mais, já que você é nosso principal VIP.",
  ui_story_5058_50580501_4_dialog_content = "Hmm, já expliquei as características das instalações do hotel para você?",
  ui_story_5058_50580501_5_dialog_content = "Ahem, além de quartos confortáveis e aconchegantes, o hotel também possui academia, piscina, fontes termais, spa...",
  ui_story_5058_50580501_6_dialog_content = "Há marcas nas escadas de cada nível, então não se preocupe em se perder.",
  ui_story_5058_50580501_7_dialog_content = "O interior também possui o sistema de ventilação mais recente, então, durante condições climáticas adversas, como uma tempestade de areia, o utilizaremos para fornecer ar fresco.",
  ui_story_5058_50580501_8_dialog_content = "Você não vai enfrentar nenhum desconforto durante uma estadia de longo prazo.",
  ui_story_5058_50580501_9_dialog_content = "Além disso, o café da manhã e o almoço são em estilo buffet, basta ir ao restaurante e você ficará bem...",
  ui_story_5058_50580501_10_dialog_content = "PlayerName!",
  ui_story_5058_50580501_11_dialog_content = "Onde você esteve? Não conseguimos te encontrar depois que saímos do brinquedo.",
  ui_story_5058_50580501_12_dialog_content = "Desculpe por isso... Eu estava experimentando o Halo Shots e conheci uma senhora chamada Shashona.",
  ui_story_5058_50580501_13_dialog_content = "Então Shashona está aqui.",
  ui_story_5058_50580501_14_dialog_content = "Você conhece ela?",
  ui_story_5058_50580501_15_dialog_content = "Como eu posso dizer isso... Ela não é alguém com quem devemos brincar.",
  ui_story_5058_50580501_16_dialog_content = "Por quê? Ela é uma pessoa importante?",
  ui_story_5058_50580501_17_dialog_content = "Shashona é na verdade a mãe de Lorelei.",
  ui_story_5058_50580501_18_dialog_content = "A mãe do Lorelei também está aqui? Como podemos celebrar o tempo do Lorelei nesse caso?",
  ui_story_5058_50580501_19_dialog_content = "Bem, devemos ser gratos por ter Bopper conosco.",
  ui_story_5058_50580501_20_dialog_content = "Aham... Obrigado a todos. Por favor, saibam que minha missão é fornecer um serviço de qualidade aos nossos hóspedes. Quanto à minha mãe... Ela vem me visitar com bastante frequência, na verdade.",
  ui_story_5058_50580501_21_dialog_content = "Ah, e estou me perguntando, o que você acha das atrações?",
  ui_story_5058_50580501_22_dialog_content = "Sinceramente, muitos daqueles foram demais para mim.",
  ui_story_5058_50580501_23_dialog_content = "Acho que são perfeitamente empolgantes. Me diverti muito.",
  ui_story_5058_50580501_24_dialog_content = "Eu posso dizer... Mas só de olhar para eles já fico cansado e adoraria uma pausa agora.",
  ui_story_5058_50580501_25_dialog_content = "Ah, ah, entendi.",
  ui_story_5058_50580501_26_dialog_content = "O Conselho de Administração sempre quis mais atrações emocionantes. Eu vejo que precisamos de mais atrações para pessoas de todas as idades.",
  ui_story_5058_50580501_27_dialog_content = "(Pessoas de todas as idades? Estamos mais ou menos da mesma idade...!)",
  ui_story_5058_50580501_28_dialog_content = "Obrigado pelo feedback valioso, PlayerName!",
  ui_story_5058_50580501_29_dialog_content = "Todo mundo está desistindo por agora, ou devemos continuar conferindo os brinquedos?",
  ui_story_5058_50580501_30_dialog_content = "Corremos bastante e estou me sentindo um pouco exausto.",
  ui_story_5058_50580501_31_dialog_content = "Sim, eu concordo... Mas ainda não coletamos todos os adesivos da Deusa Denuo!",
  ui_story_5058_50580501_32_dialog_content = "Tudo bem, você ainda tem vários dias para fazer isso.",
  ui_story_5058_50580501_33_dialog_content = "Legal, quero colecionar todos os adesivos lindos das Deusas Denuo!",
  ui_story_5058_50580501_34_dialog_content = "Falando nisso, vocês querem fazer um passeio pelo vale?",
  ui_story_5058_50580501_35_dialog_content = "Tem muitas borboletas e talvez veremos a verdadeira Deusa Denuo!",
  ui_story_5058_50580501_36_dialog_content = "Quando você descansar, posso te levar para conhecer o vale.",
  ui_story_5058_50580501_37_dialog_content = "A área ainda não está desenvolvida, mas pode se tornar parte do resort no futuro.",
  ui_story_5058_50580501_38_dialog_content = "Maravilhoso! Essa viagem valeria ainda mais a pena se víssemos a Deusa Denuo!",
  ui_story_5058_50580501_39_dialog_content = "Por que não vamos agora?",
  ui_story_5058_50580501_40_dialog_content = "Concordo.",
  ui_story_5058_50580501_41_dialog_content = "Você não queria descansar um pouco?",
  ui_story_5058_50580501_42_dialog_content = "Ouvimos que a Srta. Lorelei fez um grande esforço para tornar o Vale Denuo verde.",
  ui_story_5058_50580501_43_dialog_content = "Fico animado só de pensar na paisagem verde e exuberante!",
  ui_story_5058_50580501_44_dialog_content = "Concordo.",
  ui_story_5058_50580501_45_dialog_content = "Entendi. Por que não, vamos decolar agora!",
  ui_story_5058_50580501_46_dialog_content = "<color=#e8d9bb>Depois de um tempo...</color>",
  ui_story_5058_50580501_47_dialog_content = "Respirar...",
  ui_story_5058_50580501_48_dialog_content = "O ar está tão limpo. Respirei fundo e até minha boca se refrescou.",
  ui_story_5058_50580501_49_dialog_content = "O agradável aroma da grama me lembra de Eraveil.",
  ui_story_5058_50580501_50_dialog_content = "Sim, as plantas parecem crescer naturalmente sem nenhum sinal de artificialidade.",
  ui_story_5058_50580501_51_dialog_content = "É assim que a natureza deve ser. Basta plantar as sementes, nutri-las e elas nos surpreenderão.",
  ui_story_5058_50580501_52_dialog_content = "Isso é impressionante, Lorelei, construir um resort como este no Deserto Rediesel. Mas o que te deu essa ideia?",
  ui_story_5058_50580501_53_dialog_content = "O próprio Vale Denuo possui barreiras geográficas para isolar as incursões de Eclipsitas.",
  ui_story_5058_50580501_54_dialog_content = "E a paisagem natural aqui é completamente diferente de outros pontos turísticos em Astra.",
  ui_story_5058_50580501_55_dialog_content = "Assim, um resort proporcionaria uma experiência completamente diferente para os visitantes.",
  ui_story_5058_50580501_56_dialog_content = "Este também é um lugar muito importante para mim. É meu desejo reviver os arredores...",
  ui_story_5058_50580501_57_dialog_content = "...",
  ui_story_5058_50580501_58_dialog_content = "Entendo como você se sente. É exatamente como me sinto em relação a Eraveil.",
  ui_story_5058_50580501_59_dialog_content = "(Isso significa que é daqui que o Lorelei veio?)",
  ui_story_5058_50580501_60_dialog_content = "Ótimo discurso, mas a Srta. Lorelei é uma empresária de coração, então tudo se resume a lucros.",
  ui_story_5058_50580501_61_dialog_content = "É claro. Estou extremamente confiante no projeto!",
  ui_story_5058_50580501_62_dialog_content = "Ei, vejo borboletas.",
  ui_story_5058_50580501_63_dialog_content = "Sim! Eu vejo vários lá também!",
  ui_story_5058_50580501_64_dialog_content = "Eu me pergunto se a Deusa Denuo está entre eles.",
  ui_story_5058_50580501_65_dialog_content = "Senhorita Lorelei, p-posso ir procurar a Deusa Denuo?",
  ui_story_5058_50580501_66_dialog_content = "Você até tem uma rede pronta para usar, Bopper?!",
  ui_story_5058_50580501_67_dialog_content = "Muitas pessoas me perguntaram se é verdade que a Deusa Denuo está no vale... Eu adoraria provar isso a eles!",
  ui_story_5058_50580501_68_dialog_content = "Tudo bem, mas se encontrar com eles, tome cuidado para não machucá-los.",
  ui_story_5058_50580501_69_dialog_content = "Por que não olhamos também? Há força em números!",
  ui_story_5058_50580501_70_dialog_content = "Podemos até nos dividir para cobrir mais terreno!",
  ui_story_5058_50580501_71_dialog_content = "Você está transformando isso em outra competição, não está?",
  ui_story_5058_50580501_72_dialog_content = "Heehee, não olhe para mim dessa forma... Por que eu não me junto com Carleen desta vez então?",
  ui_story_5058_50580501_73_dialog_content = "Vamos lá, vamos! Vamos ver quem encontra a Deusa primeiro!",
  ui_story_5058_50580501_74_dialog_content = "Bocejar-",
  ui_story_5058_50580501_75_dialog_content = "Crianças... Um dia agradável como este é perfeito para um cochilo.",
  ui_story_5058_50580501_76_dialog_content = "Zzzz—Zzzz—",
  ui_story_5058_50580501_77_dialog_content = "Venha aqui, Carleen, eu encontrei!",
  ui_story_5058_50580501_78_dialog_content = "Tão rápido?",
  ui_story_5058_50580501_79_dialog_content = "Aíi está!",
  ui_story_5058_50580501_80_dialog_content = "Hã? O que é isso?",
  ui_story_5058_50580501_81_dialog_content = "Nunca vi uma mariposa tão grande antes!",
  ui_story_5058_50580501_82_dialog_content = "Fique longe de mim!!!",
  ui_story_5058_50580501_83_dialog_content = "Vocês já viram a Deusa Denuo, pequenas borboletas?",
  ui_story_5058_50580501_84_dialog_content = "Você está girando em sentido horário ao meu redor... O que você quer dizer?",
  ui_story_5058_50580501_85_dialog_content = "Hmm, acho que só consigo ler a mente de Lepidoz...",
  ui_story_5058_50580501_86_dialog_content = "O que está fazendo, PlayerName?",
  ui_story_5058_50580501_87_dialog_content = "Eu-Eu estou apenas esperando o momento certo...",
  ui_story_5058_50580501_88_dialog_content = "Não se mexa... Tem uma borboleta na sua cabeça.",
  ui_story_5058_50580501_89_dialog_content = "Cena, venha tirar nossas fotos!",
  ui_story_5058_50580501_90_dialog_content = "Bocejar-",
  ui_story_5058_50580501_91_dialog_content = "Chegando...",
  ui_story_5058_50580501_92_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5058_50580501_93_dialog_content = "Bem, todo esse esforço e ainda não encontramos a Deusa Denuo.",
  ui_story_5058_50580501_94_dialog_content = "Para ser honesto, eu também já tive dúvidas sobre a existência da Deusa Denuo.",
  ui_story_5058_50580501_95_dialog_content = "Também não tenho certeza. Você não disse que já viu um antes, Cena?",
  ui_story_5058_50580501_96_dialog_content = "Eu disse isso? Não me lembro muito bem...",
  ui_story_5058_50580501_97_dialog_content = "Alguns alegaram que viram a Deusa Denuo, mas a Deusa é, na verdade, mais um mito do que qualquer outra coisa.",
  ui_story_5058_50580501_98_dialog_content = "Muitos investidores investiram no resort simplesmente porque ouviram dizer que fica no vale.",
  ui_story_5058_50580501_99_dialog_content = "Eles queriam que fosse um truque para atrair turistas... Eu não pude contestar a decisão do Conselho.",
  ui_story_5058_50580501_100_dialog_content = "Mas quando eu vi o amor e o suporte avassaladores dos clientes pelos adesivos da Deusa Denuo e como eles estão até dispostos a pagar muito dinheiro apenas para ver um aqui, isso me deixou um pouco em pânico.",
  ui_story_5058_50580501_101_dialog_content = "Porque desde a construção até agora, nenhum de nós viu um aqui.",
  ui_story_5058_50580501_102_dialog_content = "Se a Deusa Denuo não é real, isso é propaganda enganosa e eu não quero mentir para os convidados...",
  ui_story_5058_50580501_103_dialog_content = "Mas se for real, não seria o que estou fazendo que atrairia aqueles que podem prejudicar a Deusa...",
  ui_story_5058_50580501_104_dialog_content = "Eu não quis encobrir isso. Eu simplesmente não conseguia encontrar uma solução para esse problema complicado... Eu sinto muito!",
  ui_story_5058_50580501_105_dialog_content = "Nós é que deveríamos nos desculpar pelo quão imprudentes e rudes fomos.",
  ui_story_5058_50580501_106_dialog_content = "Está tudo bem. Se a Deusa puder ser encontrada, talvez possamos proliferá-las.",
  ui_story_5058_50580501_107_dialog_content = "Além disso, sei que você nunca prejudicaria as borboletas. E eu também me diverti.",
  ui_story_5058_50580501_108_dialog_content = "É das outras pessoas que eu fico receoso...",
  ui_story_5058_50580501_109_dialog_content = "Eu posso ver que você não desiste facilmente, Lorelei. Podemos descobrir isso juntos.",
  ui_story_5058_50580501_110_dialog_content = "Sim! Eu encontrei um especialista em animais que pode ser capaz de fornecer sugestões úteis.",
  ui_story_5058_50580501_111_dialog_content = "(Especialista em animais? Não poderia ser Vic, poderia?)",
  ui_story_5058_50580501_112_dialog_content = "Ainda espero que essas borboletas tão lindas sejam reais.",
  ui_story_5058_50580501_113_dialog_content = "As borboletas nos adesivos são supostamente jovens.",
  ui_story_5058_50580501_114_dialog_content = "Dizem por aí que as Deusas adultas são enormes, esguias e brancas por completo.",
  ui_story_5058_50580501_115_dialog_content = "Quão enorme é enorme? O tamanho do lagarto, talvez?",
  ui_story_5058_50580501_116_dialog_content = "Pessoal, olhem aquele arbusto ali... Será que é a Deusa Denuo?",
  ui_story_5058_50580501_117_dialog_content = "Aonde?",
  ui_story_5058_50580501_118_dialog_content = "Lá, completamente branco...",
  ui_story_5058_50580501_119_dialog_content = "Rugido!!!",
  ui_story_5058_50580501_120_dialog_content = "Eclipsitas?",
  ui_story_5058_50580501_121_dialog_content = "Como pode haver Eclipsitas no Vale Denuo?",
  ui_story_5058_50580502_1_dialog_content = "Ah não, me separei...",
  ui_story_5058_50580502_2_dialog_content = "Sibilo—",
  ui_story_5058_50580502_3_dialog_content = "Que som é esse?",
  ui_story_5058_50580502_4_dialog_content = "Silvo-!",
  ui_story_5058_50580502_5_dialog_content = "PlayerName... PlayerName?",
  ui_story_5058_50580502_6_dialog_content = "Alguém... está chamando meu nome?",
  ui_story_5058_50580502_7_dialog_content = "Te encontrei! Pequeno encrenqueiro! Hora de voltar para casa com a mamãe para o jantar. Você sabe que as pessoas precisam comer para crescer, não é?",
  ui_story_5058_50580502_8_dialog_content = "M-Mãe...",
  ui_story_5058_50580502_9_dialog_content = "A sensação... Tão confortável, aconchegante, familiar...",
  ui_story_5058_50580502_10_dialog_content = "Venha com a mamãe. Vamos para casa.",
  ui_story_5058_50580502_11_dialog_content = "Claro...",
  ui_story_5058_50580502_12_dialog_content = "... não!",
  ui_story_5058_50580502_13_dialog_content = "Achei que estava no resort...? E ainda encontramos Eclipsitas, até.",
  ui_story_5058_50580502_14_dialog_content = "Estou sonhando? Ou tendo uma visão?",
  ui_story_5058_50580502_15_dialog_content = "Qual o problema, PlayerName? Por que você não está vindo?",
  ui_story_5058_50580502_16_dialog_content = "Eu realmente quero continuar sonhando...",
  ui_story_5058_50580502_17_dialog_content = "Mas ratos, como é que eu não consigo acordar?",
  ui_story_5058_50580502_18_dialog_content = "Se isso continuar assim, eu só posso...",
  ui_story_5058_50580502_19_option_content = "Aumento de Força!",
  ui_story_5058_50580502_20_dialog_content = "Sibilo—",
  ui_story_5058_50580502_21_dialog_content = "Estou acordado agora?",
  ui_story_5058_50580502_22_dialog_content = "...",
  ui_story_5058_50580502_23_dialog_content = "Quem é você?",
  ui_story_5058_50580502_24_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5058_50580502_25_dialog_content = "A cidade... arenosa e empoeirada... Será uma colônia Eclipsita?",
  ui_story_5058_50580502_26_dialog_content = "Estou no sonho de outra pessoa?",
  ui_story_5058_50580502_27_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50580502_28_dialog_content = "A tempestade de areia está... piorando...",
  ui_story_5058_50580502_29_dialog_content = "Eu sou...",
  ui_story_5058_50580502_30_dialog_content = "...sufocante...",
  ui_story_5058_50580601_1_dialog_content = "PlayerName!",
  ui_story_5058_50580601_2_dialog_content = "Mãe...?",
  ui_story_5058_50580601_3_dialog_content = "Acorda, PlayerName!",
  ui_story_5058_50580601_4_dialog_content = "Vice... Carleen... Pessoal?",
  ui_story_5058_50580601_5_dialog_content = "Bom, você acordou! Desculpe por deixá-lo para trás. Não percebemos até estarmos bem longe.",
  ui_story_5058_50580601_6_dialog_content = "Desculpe, provavelmente estou exausto de todas as atividades de hoje...",
  ui_story_5058_50580601_7_dialog_content = "Senti-me sonolento enquanto corria e não pude evitar adormecer, até tive sonhos estranhos dos quais simplesmente não conseguia acordar.",
  ui_story_5058_50580601_8_dialog_content = "Você me assustou...",
  ui_story_5058_50580601_9_dialog_content = "Bom ver que PlayerName está bem. Seria uma derrota para a Astra caso contrário, que não poderia ser recuperada mesmo que eu vendesse todos os meus ativos.",
  ui_story_5058_50580601_10_dialog_content = "Mas como é que há Eclipsitas aqui?",
  ui_story_5058_50580601_11_dialog_content = "Também não tenho certeza... O desfiladeiro é polêmico o suficiente para eles se aventurarem, geralmente.",
  ui_story_5058_50580601_12_dialog_content = "Contratei apenas uma pequena equipe de segurança para patrulhar os perímetros externos.",
  ui_story_5058_50580601_13_dialog_content = "Achei que isso seria suficiente para mantê-lo seguro... Foi mal!",
  ui_story_5058_50580601_14_dialog_content = "Cena, precisamos adquirir armas anti-Eclipsita assim que voltarmos.",
  ui_story_5058_50580601_15_dialog_content = "Entendido. Então, o que fazemos agora...?",
  ui_story_5058_50580601_16_dialog_content = "Vamos retornar ao parque. Precisamos de um plano para isso.",
  ui_story_5058_50580601_17_dialog_content = "Graagh!",
  ui_story_5058_50580601_18_dialog_content = "Caramba, é tão assustador!",
  ui_story_5058_50580601_19_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5058_50580601_20_dialog_content = "Uma baixa a cada tiro!",
  ui_story_5058_50580601_21_dialog_content = "Isso é mais parecido! O show está começando de uma forma muito autêntica e emocionante.",
  ui_story_5058_50580601_22_dialog_content = "O show já começou?",
  ui_story_5058_50580601_23_dialog_content = "Você não ouviu uma palavra do que eu disse, Mestre? Não vejo nenhuma besta maravilhosa aqui... Quão legítima é essa missão que você recebeu?",
  ui_story_5058_50580601_24_dialog_content = "Ah, deixa pra lá. Não vou perder mais tempo. Estou voltando para assistir ao show!",
  ui_story_5058_50580601_25_dialog_content = "É bom ser jovem... Não como esse velho conjunto de ossos que eu tenho. É melhor para mim tirar um cochilo usando a pequena bola de pêlo como travesseiro.",
  ui_story_5058_50580601_26_dialog_content = "Aaarrgh!",
  ui_story_5058_50580601_27_dialog_content = "Uau, as Eclipsitas estão realmente realistas desta vez, até os molares parecem autênticos...",
  ui_story_5058_50580601_28_dialog_content = "*Rugido*",
  ui_story_5058_50580601_29_dialog_content = "Não, mestre estúpido, isso é um verdadeiro Eclipsite!",
  ui_story_5058_50580601_30_dialog_content = "Os Eclipsitas invadiram o parque, de fato...",
  ui_story_5058_50580601_31_dialog_content = "Cena, evacue os hóspedes. Bopper, escolta todos para o hotel. Eu preciso chamar a segurança para eliminar os Eclipsitas.",
  ui_story_5058_50580601_32_dialog_content = "Sem problemas, chefe, embora a diretoria provavelmente seja mais difícil de lidar do que os Eclipsitas.",
  ui_story_5058_50580601_33_dialog_content = "...",
  ui_story_5058_50580601_34_dialog_content = "Quem prometeu que nenhum Eclipsita apareceria aqui?",
  ui_story_5058_50580601_35_dialog_content = "Você nos devia uma explicação, Lorelei!",
  ui_story_5058_50580601_36_dialog_content = "Agora não é o momento de discutir essa questão.",
  ui_story_5058_50580601_37_dialog_content = "Você está aqui, Senhora Carleen?",
  ui_story_5058_50580601_38_dialog_content = "Estou apenas ajudando meu pai com o investimento dele nos meus dias de folga, nada mais!",
  ui_story_5058_50580601_39_dialog_content = "Esclarecimento desnecessário.",
  ui_story_5058_50580601_40_dialog_content = "As Eclipsitas são realmente minha culpa e negligência, Diretores, mas a segurança de vocês é a preocupação mais importante...",
  ui_story_5058_50580601_41_dialog_content = "Por favor, siga o funcionário de volta ao hotel para abrigo. Eu vou cuidar de tudo e explicar mais tarde!",
  ui_story_5058_50580601_42_dialog_content = "Bopper, vou deixar PlayerName e amigos com você.",
  ui_story_5058_50580601_43_dialog_content = "Beleza!",
  ui_story_5058_50580601_44_dialog_content = "Mas não podemos e não devemos deixar você enfrentar tudo isso sozinho, Lorelei...",
  ui_story_5058_50580601_45_dialog_content = "Sim. Será muito mais rápido para nós removermos as Eclipsitas juntos.",
  ui_story_5058_50580601_46_dialog_content = "Isso mesmo, todos nós somos experientes, você sabe!",
  ui_story_5058_50580601_47_dialog_content = "Isso é inesperado. Eu não achei que você faria...",
  ui_story_5058_50580601_48_dialog_content = "Ei, são aqueles Vic e Fia? Eles também estão lutando!",
  ui_story_5058_50580601_49_dialog_content = "Vamos nos livrar dos Eclipsitas ao nosso redor e depois nos juntar a eles!",
  ui_story_5058_50580601_50_dialog_content = "Sim!",
  ui_story_5058_50580601_51_dialog_content = "Vejo que sou obrigado a lutar ao lado de vocês camponeses pelo bem da Senhora Carleen.",
  ui_story_5058_50580702_1_dialog_content = "Todos os Eclipsitas nas proximidades imediatas foram tratados. Obrigado a todos pela ajuda.",
  ui_story_5058_50580702_2_dialog_content = "Mas eu preciso insistir que você se abrigue no hotel e deixe o resto comigo.",
  ui_story_5058_50580702_3_dialog_content = "Você sempre diz \"Deixe-me cuidar do resto\", mas nada é tão simples assim.",
  ui_story_5058_50580702_4_dialog_content = "Shashona...",
  ui_story_5058_50580702_5_dialog_content = "Eu não queria que você viesse aqui e construísse um resort. E, claro, algo ruim está acontecendo!",
  ui_story_5058_50580702_6_dialog_content = "Você viu a cara dos diretores também. Eles não acham que você consegue realizar isso de jeito nenhum.",
  ui_story_5058_50580702_7_dialog_content = "Faça como eu digo e feche o parque agora.",
  ui_story_5058_50580702_8_dialog_content = "Mãe, como você pode ser tão irresponsável agora?",
  ui_story_5058_50580702_9_dialog_content = "Não posso deixar minha equipe e convidados na mão, nem posso trair os investidores.",
  ui_story_5058_50580702_10_dialog_content = "Você sabe o que eu passei para construir este resort?",
  ui_story_5058_50580702_11_dialog_content = "Você quer que eu desligue isso bem quando está prestes a ser lançado?",
  ui_story_5058_50580702_12_dialog_content = "Sei que você fez muitos sacrifícios, por isso acho que isso não vale a pena!",
  ui_story_5058_50580702_13_dialog_content = "A família ajudaria você com qualquer coisa que quisesse fazer, mas você insistiu em ir sozinho...",
  ui_story_5058_50580702_14_dialog_content = "Não se preocupe comigo, mãe. Volte para o hotel e eu trato de tudo.",
  ui_story_5058_50580702_15_dialog_content = "Mas não importa o que aconteça, eu não vou fechar o parque.",
  ui_story_5058_50580702_16_dialog_content = "Ouça-me, Laurie...",
  ui_story_5058_50580702_17_dialog_content = "Sra. Shashona!",
  ui_story_5058_50580702_18_dialog_content = "Cena está aqui. Ele pode te levar. Ainda tenho muitos negócios para cuidar.",
  ui_story_5058_50580702_19_dialog_content = "Faz muito tempo, Sra. Shashona.",
  ui_story_5058_50580702_20_dialog_content = "...",
  ui_story_5058_50580702_21_dialog_content = "Isso é uma farsa!",
  ui_story_5058_50580702_22_dialog_content = "O hotel fica por ali...",
  ui_story_5058_50580702_23_dialog_content = "Bopper, estou preocupado que alguns convidados ainda possam estar no parque. Vou enviar a segurança para verificar novamente.",
  ui_story_5058_50580702_24_dialog_content = "Você e os funcionários do hotel verificam com os hóspedes para atender às suas necessidades.",
  ui_story_5058_50580702_25_dialog_content = "Te vejo depois de verificar as medidas de emergência do hotel.",
  ui_story_5058_50580702_26_dialog_content = "Hã? Mas isso não está na descrição do meu trabalho...",
  ui_story_5058_50580702_27_dialog_content = "PlayerName, Vice, Carleen, vocês devem voltar para seus quartos. Eu vou encontrar vocês depois que as coisas se acalmarem.",
  ui_story_5058_50580702_28_dialog_content = "Você está com poucas pessoas agora, Srta. Lorelei. Deixe-nos ajudar.",
  ui_story_5058_50580702_29_dialog_content = "Eu, por exemplo, não quero ser tratado como um turista comum! Nós perseguimos borboletas e lutamos contra Eclipsitas juntos, e isso nos torna amigos!",
  ui_story_5058_50580702_30_dialog_content = "Obrigado, mas eu preciso fazer isso sozinho. Você viu o que aconteceu...",
  ui_story_5058_50580702_31_dialog_content = "Porque sua mãe se opôs? Na verdade, entendo o quanto você quer fazer isso sozinho.",
  ui_story_5058_50580702_32_dialog_content = "Fui muito duro com minha mãe?",
  ui_story_5058_50580702_33_dialog_content = "Há algo em sua mente, Lorelei? Nós vamos ouvir se você não se importar...",
  ui_story_5058_50580702_34_dialog_content = "Sim, não guarde isso dentro de você.",
  ui_story_5058_50580702_35_dialog_content = "Bem, eu não queria agir dessa forma, mas por algum motivo, nunca me dei bem com minha mãe desde que comecei a viver sozinha.",
  ui_story_5058_50580702_36_dialog_content = "Eu sei que ela me ama muito. Ela tolera e aceita tudo o que eu faço, exceto começar meu próprio negócio...",
  ui_story_5058_50580702_37_dialog_content = "E é exatamente por isso que eu tenho que provar que posso lidar com as coisas sozinho.",
  ui_story_5058_50580702_38_dialog_content = "Quanto mais ela tenta me impedir, mais eu luto para me defender...",
  ui_story_5058_50580702_39_dialog_content = "Isso provavelmente é infantil, mas eu simplesmente não consigo me controlar...",
  ui_story_5058_50580702_40_dialog_content = "É difícil para uma pessoa fazer uma introspecção como você acabou de fazer. Eu entendo sua mãe, no entanto, ela tem medo que você se machuque...",
  ui_story_5058_50580702_41_dialog_content = "Sim, ela não está te culpando nem nada. Ela só está preocupada com você.",
  ui_story_5058_50580702_42_dialog_content = "EveTodo mundo perde o controle às vezes, mas um pouco de compreensão mútua será suficiente.",
  ui_story_5058_50580702_43_dialog_content = "Espero que seja esse o caso também.",
  ui_story_5058_50580702_44_dialog_content = "Mas para evitar que ela tente me impedir de fazer qualquer coisa no futuro, eu preciso superar esse perigo em mãos.",
  ui_story_5058_50580702_45_dialog_content = "Apenas peça desculpas a ela depois que tudo se acalmar.",
  ui_story_5058_50580702_46_dialog_content = "Certo! Eu realmente sinto um peso saindo dos meus ombros.",
  ui_story_5058_50580702_47_dialog_content = "Então deixe-nos fazer parte do seu plano de gerenciamento de crises!",
  ui_story_5058_50580702_48_dialog_content = "Vamos enfrentar isso juntos, e então ela o verá sob uma nova luz, com certeza!",
  ui_story_5058_50580702_49_dialog_content = "Não esqueça dos seus trabalhadores com Chave Rediesel também.",
  ui_story_5058_50580702_50_dialog_content = "Obrigado.",
  ui_story_5058_50580702_51_dialog_content = "Então, quais são suas instruções, chefe?",
  ui_story_5058_50580702_52_dialog_content = "Primeiro, precisamos manter os convidados calmos e garantir a segurança deles.",
  ui_story_5058_50580702_53_dialog_content = "Assim que garantirmos o perímetro do hotel, encontre todas as falhas e tome medidas adequadas para corrigi-las.",
  ui_story_5058_50580702_54_dialog_content = "Há o trabalho para sua equipe de Chave Rediesel, Bopper.",
  ui_story_5058_50580702_55_dialog_content = "Tudo bem, desde que eles sejam pagos.",
  ui_story_5058_50580801_1_dialog_content = "Não tenha tanta pressa, Sra. Shashona...",
  ui_story_5058_50580801_2_dialog_content = "Uau, por que não nos acalmamos e guardamos essa arma?",
  ui_story_5058_50580801_3_dialog_content = "Não há nada para conversar com um charlatão como você.",
  ui_story_5058_50580801_4_dialog_content = "Por que você voltou para Lorelei desta vez?",
  ui_story_5058_50580801_5_dialog_content = "Você entendeu tudo errado, é apenas uma coincidência...",
  ui_story_5058_50580801_6_dialog_content = "Coincidência? Estou adivinhando que você descobriu que Lorelei é uma garota rica agora e queria enganá-la?",
  ui_story_5058_50580801_7_dialog_content = "Você era apenas um servo que meu marido e eu contratamos em uma de nossas viagens.",
  ui_story_5058_50580801_8_dialog_content = "Um dia, você trouxe Lorelei para mim e pediu um adiantamento para levá-la ao doutor.",
  ui_story_5058_50580801_9_dialog_content = "Não aguentava vê-la chorar, então decidi acolhê-la.",
  ui_story_5058_50580801_10_dialog_content = "Se você realmente pretendia ajudá-la ou não, eu já te paguei uma boa quantia.",
  ui_story_5058_50580801_11_dialog_content = "E você também me prometeu que nunca mais estaria perto dela.",
  ui_story_5058_50580801_12_dialog_content = "Apenas para você aparecer mais de dez anos depois e então ela levantar um alvoroço sobre lançar um resort no Vale Denuo imediatamente. Você chama isso de coincidência?",
  ui_story_5058_50580801_13_dialog_content = "Ouça-me, Sra. Shashona, eu realmente conheci Lorelei por pura coincidência.",
  ui_story_5058_50580801_14_dialog_content = "E decidi ajudar porque admirei a ideia dela de tornar o vale verde.",
  ui_story_5058_50580801_15_dialog_content = "Você também sabe muito bem que eu faço trabalhos estranhos e preciso ganhar a vida.",
  ui_story_5058_50580801_16_dialog_content = "Então, o que você fez além de receber pagamento? Este vale é totalmente inseguro.",
  ui_story_5058_50580801_17_dialog_content = "Só percebi quando vi os adesivos de borboleta hoje... Este é realmente o lugar de onde você e Lorelei vieram, não é?",
  ui_story_5058_50580801_18_dialog_content = "A própria vila amaldiçoada pela Deusa Denuo, como você explicou naquela época...",
  ui_story_5058_50580801_19_dialog_content = "O alvoroço sobre a Deusa em todo o parque está me dando a sensação de que algo está prestes a levar Lorelei embora...",
  ui_story_5058_50580801_20_dialog_content = "\"Amaldiçoado pela Deusa Denuo\"... Como você pode dizer isso tão tranquilamente?",
  ui_story_5058_50580801_21_dialog_content = "Eu nunca quis mencionar a vila.",
  ui_story_5058_50580801_22_dialog_content = "Even ao colocar meu pé de volta neste solo novamente, a destruição passada ainda me assombra...",
  ui_story_5058_50580801_23_dialog_content = "Mas quando eu vi o quão determinado e dedicado Lorelei estava em transformar gradualmente o vale, eu finalmente também vi esperança...",
  ui_story_5058_50580801_24_dialog_content = "Então você admite que está ajudando Lorelei a reconstruir sua casa?",
  ui_story_5058_50580801_25_dialog_content = "Ela sabe que você foi quem a salvou?",
  ui_story_5058_50580801_26_dialog_content = "...",
  ui_story_5058_50580801_27_dialog_content = "E esse é o plano abrangente para o resort e para tornar todo o cânion verde. O que você achou?",
  ui_story_5058_50580801_28_dialog_content = "Isso não é um plano, mocinha.",
  ui_story_5058_50580801_29_dialog_content = "Restaurar a natureza, eternizar a experiência de ir ao parque com os pais... É apenas uma perda do meu tempo.",
  ui_story_5058_50580801_30_dialog_content = "Ouça-me, Chefe Sinsa, prometo o melhor pagamento para todos que trabalham no projeto!",
  ui_story_5058_50580801_31_dialog_content = "Quantos profissionais habilidosos a Rediesel Wrench possui, eles precisam de um palco para mostrar...",
  ui_story_5058_50580801_32_dialog_content = "Não há nada para discutir. Nós trabalhando para outra pessoa? Nem pense...",
  ui_story_5058_50580801_33_dialog_content = "Estou interessado. Mayposso ajudar.",
  ui_story_5058_50580801_34_dialog_content = "Ei, você não é Cena?",
  ui_story_5058_50580801_35_dialog_content = "Você ainda se lembra de mim?",
  ui_story_5058_50580801_36_dialog_content = "Não me diga que vocês são irmãos perdidos há muito tempo ou algo parecido!",
  ui_story_5058_50580801_37_dialog_content = "Claro que me lembro de você. Como posso esquecer a pessoa que me salvou?",
  ui_story_5058_50580801_38_dialog_content = "Onde você foi? Eu continuei esperando poder te ver novamente.",
  ui_story_5058_50580801_39_dialog_content = "...",
  ui_story_5058_50580801_40_dialog_content = "Entendi. Provavelmente, a mamãe não queria você perto de mim.",
  ui_story_5058_50580801_41_dialog_content = "Mas é tão bom ver você de novo!",
  ui_story_5058_50580801_42_dialog_content = "Aham... Desculpe, quase esqueci que vim aqui a negócios.",
  ui_story_5058_50580801_43_dialog_content = "Vamos começar de novo. Meu nome é Lorelei Cardogon. É um prazer!",
  ui_story_5058_50580801_44_dialog_content = "Ah, e não conte à mãe que eu ainda lembro de você.",
  ui_story_5058_50580801_45_dialog_content = "Claro. Boa sorte com o combinado.",
  ui_story_5058_50580801_46_dialog_content = "Espere, você mencionou que quer ajudar, mas sou muito rigoroso quando se trata de contratar.",
  ui_story_5058_50580801_47_dialog_content = "Você terá que passar por uma avaliação antes de começar!",
  ui_story_5058_50580801_48_dialog_content = "Ei, é assim que você trata alguém que te salvou?",
  ui_story_5058_50580801_49_dialog_content = "Hmm, você parece ser interessante, Lorelei. Maytalvez eu possa projetar alguns passeios para você também.",
  ui_story_5058_50580801_50_dialog_content = "Isso será ótimo, Chefe Sinsa! Eu sabia que o Deserto Rediesel é realmente um lugar legal.",
  ui_story_5058_50580801_51_dialog_content = "Não se preocupe, eu não disse nada. Para ela, sou apenas um funcionário.",
  ui_story_5058_50580801_52_dialog_content = "E por favor, relaxe, Lorelei é um ótimo jovem. Você está preocupado com coisas que não vão acontecer.",
  ui_story_5058_50580801_53_dialog_content = "Não vai acontecer? Então o que eram aqueles Eclipsitas?",
  ui_story_5058_50580801_54_dialog_content = "Uau, o estresse que estou sentindo... Você não acredita que ela possa lidar com isso? Ou...",
  ui_story_5058_50580801_55_dialog_content = "Você tem medo de que, se ela resolver essa crise, ela ficaria forte o suficiente para... te deixar?",
  ui_story_5058_50580801_56_dialog_content = "Hmm, até me pergunto se você trouxe os Eclipsitas de propósito...",
  ui_story_5058_50580801_57_dialog_content = "E deixar que machuquem meu filho? Isso é algo que uma mãe faria?",
  ui_story_5058_50580801_58_dialog_content = "Sempre a tratei como minha própria filha. Por que eu não gostaria de vê-la ter sucesso?",
  ui_story_5058_50580801_59_dialog_content = "Ficar de pé... Conduzir a própria vida...",
  ui_story_5058_50580801_60_dialog_content = "Sei que isso vai acontecer mais cedo ou mais tarde.",
  ui_story_5058_50580801_61_dialog_content = "Tudo que posso esperar é que seja mais tarde para que eu possa preparar um caminho melhor para ela...",
  ui_story_5058_50580801_62_dialog_content = "Heh, tão compreensivo, mas tão difícil de deixar ir!",
  ui_story_5058_50580801_63_dialog_content = "<size=45>Graaaah!</size>",
  ui_story_5058_50580801_64_dialog_content = "Vamos falar sobre isso depois. Vamos acabar com os Eclipsitas primeiro, Sra. Shashona.",
  ui_story_5058_50580802_1_dialog_content = "Feito.",
  ui_story_5058_50580802_2_dialog_content = "Você realmente é um atirador de elite, Sra. Shashona.",
  ui_story_5058_50580802_3_dialog_content = "Espere... Essa sensação... É a mesma de antes...",
  ui_story_5058_50580802_4_dialog_content = "Será que...",
  ui_story_5058_50580802_5_dialog_content = "O que você está dizendo, Cena?",
  ui_story_5058_50580802_6_dialog_content = "Nah, não pode ser, está tudo resolvido...",
  ui_story_5058_50580802_7_dialog_content = "Desculpe, Sra. Shashona, não posso acompanhá-la de volta. Algo surgiu de repente.",
  ui_story_5058_50580802_8_dialog_content = "Aonde você tá indo?",
  ui_story_5058_50580802_9_dialog_content = "Você sabe que o vale e o Lorelei estão em perigo, não é?",
  ui_story_5058_50580802_10_dialog_content = "<size=45>Ei...!</size>",
  ui_story_5058_50580901_1_dialog_content = "Você voltou, Lorelei! Como está lá fora?",
  ui_story_5058_50580901_2_dialog_content = "Sem sinal de Eclipsitas por enquanto, mas ainda não temos ideia do porquê eles invadiriam de repente...",
  ui_story_5058_50580901_3_dialog_content = "O que está acontecendo com os convidados?",
  ui_story_5058_50580901_4_dialog_content = "Ajudamos todos eles a chegarem aos seus quartos, mas o gerente e o Shashona não estão em lugar nenhum...",
  ui_story_5058_50580901_5_dialog_content = "Cena e minha mãe? Você checou todos os cantos do hotel?",
  ui_story_5058_50580901_6_dialog_content = "Sim, em todo lugar.",
  ui_story_5058_50580901_7_dialog_content = "Obrigado por me informar, Bopper. Por favor, avise a equipe de segurança para montar defesas ao redor do hotel.",
  ui_story_5058_50580901_8_dialog_content = "Além disso, lembre a equipe de preparar e entregar as refeições aos hóspedes pontualmente, sem um segundo de atraso...",
  ui_story_5058_50580901_9_dialog_content = "*Rugido*",
  ui_story_5058_50580901_10_dialog_content = "O quê?",
  ui_story_5058_50580901_11_dialog_content = "Gelescer!",
  ui_story_5058_50580901_12_dialog_content = "Uau, que reflexos rápidos, Carleen! Você matou o Eclipsita antes mesmo de eu saber que ele estava lá!",
  ui_story_5058_50580901_13_dialog_content = "Mas como eles conseguiram...",
  ui_story_5058_50580901_14_dialog_content = "Dentro... do hotel...",
  ui_story_5058_50580901_15_dialog_content = "Lorelei...? Você...",
  ui_story_5058_50580901_16_dialog_content = "Meus olhos... não consigo mantê-los abertos...",
  ui_story_5058_50580901_17_dialog_content = "PlayerName...",
  ui_story_5058_50580901_18_dialog_content = "...",
  ui_story_5058_50580901_19_dialog_content = "Vice... Carleen...?!",
  ui_story_5058_50580901_20_dialog_content = "O que está... acontecendo...",
  ui_story_5058_50580901_21_dialog_content = "PlayerName... PlayerName?",
  ui_story_5058_50580901_22_dialog_content = "Hã?",
  ui_story_5058_50580901_23_dialog_content = "Te encontrei! Pequeno encrenqueiro! Hora de voltar para casa com a mamãe para o jantar. Você sabe que as pessoas precisam comer para crescer, não é?",
  ui_story_5058_50580901_24_dialog_content = "Outro sonho?",
  ui_story_5058_50580901_25_dialog_content = "De novo? Mas desta vez, embora...",
  ui_story_5058_50580901_26_option_content = "Vamos, acorda!",
  ui_story_5058_50580901_27_dialog_content = "Ufa... O que aconteceu? Foi exatamente igual quando desmaiei no vale.",
  ui_story_5058_50580901_28_dialog_content = "EveTodo mundo está fora...",
  ui_story_5058_50580901_29_dialog_content = "Lorelei? Lorelei! Acorda!",
  ui_story_5058_50580901_30_dialog_content = "Mãe... mãe...",
  ui_story_5058_50580901_31_dialog_content = "Vice! Carleen!",
  ui_story_5058_50580901_32_dialog_content = "Preciso cozinhar... criar novos pratos...",
  ui_story_5058_50580901_33_dialog_content = "...",
  ui_story_5058_50580901_34_dialog_content = "Todos estão em transe? Ei, o que é aquele piscar no ar?",
  ui_story_5058_50580901_35_dialog_content = "Está em todo lugar, por todo o hotel! Foi isso que desmaiou as pessoas?",
  ui_story_5058_50580901_36_dialog_content = "O que eu vou fazer? Posso acordá-los telepaticamente... Não, abra a janela e deixe o ar fresco entrar.",
  ui_story_5058_50580901_37_dialog_content = "Mas então, os Eclipsitas do lado de fora não poderão entrar?",
  ui_story_5058_50580901_38_dialog_content = "Hmm, o Lorelei não mencionou um sistema de ventilação? Vamos ligar isso!",
  ui_story_5058_50580901_39_dialog_content = "O problema é que eu não sei onde está o interruptor.",
  ui_story_5058_50580901_40_dialog_content = "Lorelei saberia com certeza! Sim, vou acordá-la primeiro!",
  ui_story_5058_50580901_41_option_content = "Aumento de Força!",
  ui_story_5058_50580901_42_dialog_content = "Você está dormindo, Lorelei?",
  ui_story_5058_50580901_43_dialog_content = "Não, estou apenas ouvindo mamãe me contar uma história de olhos fechados!",
  ui_story_5058_50580901_44_dialog_content = "(Esta deve ser a memória de Lorelei.)",
  ui_story_5058_50580901_45_dialog_content = "(É aquela garotinha Lorelei? Mas a mãe dela não parece Shashona!)",
  ui_story_5058_50580901_46_dialog_content = "(E aquele jovem ali é a figura que eu vi quando desmaiei no vale!)",
  ui_story_5058_50580901_47_dialog_content = "A lenda diz que o Vale Denuo é livre de Eclipsitas porque estamos sob a proteção da <color=#FFB400>Deusa Denuo</color>.",
  ui_story_5058_50580901_48_dialog_content = "Borboletas? Você quer dizer as que estão ao nosso redor?",
  ui_story_5058_50580901_49_dialog_content = "As Deusas Denuo não são borboletas comuns. Elas têm asas tão brilhantes quanto diamantes.",
  ui_story_5058_50580901_50_dialog_content = "EveTodos que veem uma Deusa receberão a bênção de revelação e alegria incomparáveis.",
  ui_story_5058_50580901_51_dialog_content = "Sério? Quando eu vou poder ver um?",
  ui_story_5058_50580901_52_dialog_content = "Oh criança, não é fácil ver uma Deusa.",
  ui_story_5058_50580901_53_dialog_content = "A história diz que eles vivem no Vale Denuo, mas raramente se mostram para alguém.",
  ui_story_5058_50580901_54_dialog_content = "Acho que vi uma jovem Deusa Denuo alguns dias atrás.",
  ui_story_5058_50580901_55_dialog_content = "Não conseguia tirar os olhos daquele brilho incrível das asas... Basta um olhar e você nunca esquecerá!",
  ui_story_5058_50580901_56_dialog_content = "Ouvi dizer que a jovem Deusa Denuo raramente crescia até a maturidade e estava presa em uma teia de aranha, então eu a libertei.",
  ui_story_5058_50580901_57_dialog_content = "Uau! Então você recebeu a bênção?",
  ui_story_5058_50580901_58_dialog_content = "Maynão seja...?",
  ui_story_5058_50580901_59_dialog_content = "Vamos lá, Cena, não me diga que você nunca viu um! Não é bom mentir!",
  ui_story_5058_50580901_60_dialog_content = "(Aquele homem jovem é realmente Cena? Então eles se conheciam antes?)",
  ui_story_5058_50580901_61_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh!</color>",
  ui_story_5058_50580901_62_dialog_content = "Mãe! Cena! Onde você tá?",
  ui_story_5058_50580901_63_dialog_content = "Tempestade de areia! Está engolindo a vila inteira!",
  ui_story_5058_50580901_64_dialog_content = "Nós merecemos isso por enfurecer a Deusa Denuo!",
  ui_story_5058_50580901_65_dialog_content = "Mãe... Não me deixe para trás...",
  ui_story_5058_50580901_66_dialog_content = "Pegue minha mão, Lorelei!",
  ui_story_5058_50580901_67_dialog_content = "Cena...?",
  ui_story_5058_50580901_68_dialog_content = "Sou eu, PlayerName!",
  ui_story_5058_50580901_69_dialog_content = "PlayerName...?",
  ui_story_5058_50580901_70_option_content = "Acorda!",
  ui_story_5058_50580901_71_dialog_content = "Ahn???",
  ui_story_5058_50580901_72_dialog_content = "Você finalmente acordou, Lorelei! Não se assuste, sou só eu!",
  ui_story_5058_50580901_73_dialog_content = "PlayerName? O que houve?",
  ui_story_5058_50580901_74_dialog_content = "Eu não sei, mas todos desmaiaram de repente.",
  ui_story_5058_50580901_75_dialog_content = "Então percebi que havia algo estranho no ar.",
  ui_story_5058_50580901_76_dialog_content = "Algo que continuava piscando.",
  ui_story_5058_50580901_77_dialog_content = "Eles devem estar relacionados a todos ficarem inconscientes. Se ligássemos o sistema de ventilação que você mencionou, ele se livraria dessas coisas?",
  ui_story_5058_50580901_78_dialog_content = "O interruptor está perto. Me siga!",
  ui_story_5058_50580901_79_dialog_content = "Graagh!",
  ui_story_5058_50580901_80_dialog_content = "Mais Eclipsitas?",
  ui_story_5058_50580901_81_dialog_content = "Só nós dois restantes... Me dê uma mão, PlayerName!",
  ui_story_5058_50581001_1_dialog_content = "Grrr!",
  ui_story_5058_50581001_2_dialog_content = "Ahhhh!",
  ui_story_5058_50581001_3_dialog_content = "Você não pode me matar assim!",
  ui_story_5058_50581001_4_dialog_content = "Sem falar que essa vida não é mais minha agora, então, desculpe, não posso deixar você ficar com ela!",
  ui_story_5058_50581001_5_dialog_content = "Mas muito em breve, quando eu ver <color=#FFB400>\"ela\"</color>... Por outro lado, \"ela\" provavelmente te atraiu até aqui.",
  ui_story_5058_50581001_6_dialog_content = "Ainda quero ver \"ela\", porém, e me arrepender pessoalmente...",
  ui_story_5058_50581001_7_dialog_content = "(Cena enlouqueceu? Quem é que ele quer ver?)",
  ui_story_5058_50581001_8_dialog_content = "*Rugido*",
  ui_story_5058_50581001_9_dialog_content = "Cuidado!",
  ui_story_5058_50581001_10_dialog_content = "Sra. Shashona?",
  ui_story_5058_50581001_11_dialog_content = "O que você está fazendo, Cena? Por que está tentando ser um herói quando deveria estar no hotel ajudando Lorelei?",
  ui_story_5058_50581001_12_dialog_content = "Isso não tem nada a ver com você. Eu preciso enfrentar o que tem me incomodado na maior parte da minha vida sozinho. Eu tenho que fazer isso por mim mesmo...",
  ui_story_5058_50581001_13_dialog_content = "Obrigado por cuidar e olhar pelo Lorelei para mim...",
  ui_story_5058_50581001_14_dialog_content = "Ela é adulta agora. Você deve ouvir o que ela tem a dizer, pare de ditar tudo para ela.",
  ui_story_5058_50581001_15_dialog_content = "É isso. Por favor, vá embora.",
  ui_story_5058_50581001_16_dialog_content = "Você está me dando suas últimas palavras?",
  ui_story_5058_50581001_17_dialog_content = "Aaaaaah!",
  ui_story_5058_50581001_18_dialog_content = "Vamos lá, venha até mim!",
  ui_story_5058_50581001_19_dialog_content = "Carregando as Eclipsitas assim, do nada? Você perdeu a cabeça, Cena?!",
  ui_story_5058_50581001_20_dialog_content = "Isso está me dando dor de cabeça.",
  ui_story_5058_50581001_21_dialog_content = "Infelizmente, eu não sou alguém que fica parado assistindo outra pessoa morrer.",
  ui_story_5058_50581001_22_dialog_content = "Tudo bem, venha experimentar minhas novas balas personalizadas e veja se você gosta delas!",
  ui_story_5058_50581001_23_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5058_50581001_24_dialog_content = "Argh!",
  ui_story_5058_50581001_25_dialog_content = "Eu imploro, Shashona, me deixe em paz...",
  ui_story_5058_50581001_26_dialog_content = "Deixar você em paz? Como isso sempre saiu tão facilmente da sua língua e da de Lorelei?",
  ui_story_5058_50581001_27_dialog_content = "Lorelei e eu somos diferentes. Você ainda não entendeu. Ela nunca quis se afastar de você.",
  ui_story_5058_50581001_28_dialog_content = "O motivo pelo qual ela queria construir um parque de diversões é porque ela valorizava as lembranças de você levando-a lá.",
  ui_story_5058_50581001_29_dialog_content = "Foi isso que ela te disse? Aquela criança...",
  ui_story_5058_50581001_30_dialog_content = "Eu sei disso. Eu descobri quando li o plano de negócios dela. Eu só estava...",
  ui_story_5058_50581001_31_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_32_dialog_content = "O vento está soprando no vale...?",
  ui_story_5058_50581001_33_dialog_content = "<color=#e8d9bb>Hiss—</color>",
  ui_story_5058_50581001_34_dialog_content = "Chegando...",
  ui_story_5058_50581001_35_dialog_content = "\"Ela\" está chegando!",
  ui_story_5058_50581001_36_dialog_content = "Quem está vindo?",
  ui_story_5058_50581001_37_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_38_dialog_content = "Sibilo—Sibilo—",
  ui_story_5058_50581001_39_dialog_content = "<color=#FFB400>Deusa Denuo</color>... Finalmente, eu te vejo!",
  ui_story_5058_50581001_40_dialog_content = "Fugi da aldeia e passei metade da minha vida vagando por todo o Astra apenas para perceber...",
  ui_story_5058_50581001_41_dialog_content = "Meu coração nunca deixou Denuo!",
  ui_story_5058_50581001_42_dialog_content = "Vejo que você veio em busca de sua vingança, Deusa Denuo.",
  ui_story_5058_50581001_43_dialog_content = "Sim, eu não deveria ter sobrevivido. Eu pensei que poderia ganhar anistia reconstruindo o vale...",
  ui_story_5058_50581001_44_dialog_content = "Por favor, aplique em mim a punição final!",
  ui_story_5058_50581001_45_dialog_content = "É aquela a Deusa Denuo que infligiu a maldição?",
  ui_story_5058_50581001_46_dialog_content = "Acalme-se, Cena! É apenas uma borboleta maior que o normal!",
  ui_story_5058_50581001_47_dialog_content = "Eu não acredito que uma simples borboleta possa controlar nossas vidas!",
  ui_story_5058_50581001_48_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_49_dialog_content = "Sibilo!",
  ui_story_5058_50581001_50_dialog_content = "O que está sendo lançado?",
  ui_story_5058_50581001_51_dialog_content = "Aaarrgh!",
  ui_story_5058_50581001_52_dialog_content = "Mais Eclipsitas estão aparecendo...",
  ui_story_5058_50581001_53_dialog_content = "Entendi, a borboleta levou os Eclipsitas ao vale! Cena!",
  ui_story_5058_50581001_54_dialog_content = "Cena?",
  ui_story_5058_50581001_55_dialog_content = "Por favor, me puna...",
  ui_story_5058_50581001_56_dialog_content = "Levante-se agora e lute contra os Eclipsos!",
  ui_story_5058_50581002_1_dialog_content = "Argh...",
  ui_story_5058_50581002_2_dialog_content = "Estou tonto... O que está acontecendo...? Não consigo me segurar...",
  ui_story_5058_50581002_3_dialog_content = "Cena... Cena...",
  ui_story_5058_50581002_4_dialog_content = "Correr... Correr...",
  ui_story_5058_50581002_5_dialog_content = "Hã?",
  ui_story_5058_50581002_6_dialog_content = "Correr...",
  ui_story_5058_50581002_7_dialog_content = "Correr...",
  ui_story_5058_50581002_8_dialog_content = "Por que você me salvou? Pessoas como eu não valem o esforço...",
  ui_story_5058_50581002_9_dialog_content = "Correr... Pegue Lorelei e... correr...!",
  ui_story_5058_50581002_10_dialog_content = "...",
  ui_story_5058_50581002_11_dialog_content = "Ai...",
  ui_story_5058_50581002_12_dialog_content = "Sra. Shashona?!",
  ui_story_5058_50581002_13_dialog_content = "Coco, Shashona... Por que vocês dois salvariam alguém que nunca levou a vida a sério como eu?",
  ui_story_5058_50581002_14_dialog_content = "<size=45>Chiado, chiado, chiado!</size>",
  ui_story_5058_50581002_15_dialog_content = "Gruau!",
  ui_story_5058_50581002_16_dialog_content = "Mas eu sou quem não deveria ser perdoado, não Shashona...",
  ui_story_5058_50581002_17_dialog_content = "Sra. Shashona! Consegue me ouvir?! Shashona!",
  ui_story_5058_50581002_18_dialog_content = "Não...",
  ui_story_5058_50581002_19_dialog_content = "<color=#e8d9bb>*Batida*</color>",
  ui_story_5058_50581002_20_dialog_content = "Venha aqui, Shashona! Para onde sua mãe foi?",
  ui_story_5058_50581002_21_dialog_content = "Não sei mesmo.",
  ui_story_5058_50581002_22_dialog_content = "Pare de chorar! Você não sabe? Como assim você não sabe? Sua mãe fugiu, entendeu?! É tudo culpa sua!",
  ui_story_5058_50581002_23_dialog_content = "*soluçando*",
  ui_story_5058_50581002_24_dialog_content = "Onde ela guardou o dinheiro?",
  ui_story_5058_50581002_25_dialog_content = "Papai... Nossa loja está endividada. Mamãe disse que devemos economizar cada centavo, não para você gastar com bebida.",
  ui_story_5058_50581002_26_dialog_content = "Por que você ainda ouve ela quando ela nem te quer mais? Vejo que você precisa de uma boa surra!",
  ui_story_5058_50581002_27_dialog_content = "<color=#e8d9bb>Tapa! Tapa!</color>",
  ui_story_5058_50581002_28_dialog_content = "...",
  ui_story_5058_50581002_29_dialog_content = "Pobre criança... Não se preocupe, prometo cuidar de você até que esteja saudável novamente.",
  ui_story_5058_50581002_30_dialog_content = "Desde a primeira vez que te vi, eu soube que você é a filha enviada para mim lá de cima, compensando minha infância...",
  ui_story_5058_50581002_31_dialog_content = "Saí do pântano aos poucos, apenas depois de todos os anos de pesadelo.",
  ui_story_5058_50581002_32_dialog_content = "A partir de agora, vou fazer de você a garota mais feliz do mundo, nunca mais será machucada.",
  ui_story_5058_50581002_33_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_5058_50581002_34_dialog_content = "Onde estou?",
  ui_story_5058_50581002_35_dialog_content = "Lorelei, meu amor, saia da chuva e venha até mim!",
  ui_story_5058_50581002_36_dialog_content = "Por que você me deixaria entrar debaixo do seu guarda-chuva?",
  ui_story_5058_50581002_37_dialog_content = "Porque... eu estive na chuva quando era criança e não foi bom.",
  ui_story_5058_50581002_38_dialog_content = "Então eu não quero que você se molhe na chuva ou se machuque. Quero que você se preocupe apenas em crescer seguro e saudável.",
  ui_story_5058_50581002_39_dialog_content = "Mas quem é você? Por que você é tão bom para mim?",
  ui_story_5058_50581002_40_dialog_content = "Esqueceu que sou sua mãe? Você tem um pai e um irmãozinho também. Somos a família mais feliz do mundo.",
  ui_story_5058_50581002_41_dialog_content = "Há algo que você deseja, querido? Posso realizar todos os seus desejos!",
  ui_story_5058_50581002_42_dialog_content = "Posso ler livros de histórias?",
  ui_story_5058_50581002_43_dialog_content = "Sim!",
  ui_story_5058_50581002_44_dialog_content = "Posso usar vestidos bonitos?",
  ui_story_5058_50581002_45_dialog_content = "Sim!",
  ui_story_5058_50581002_46_dialog_content = "E... e...",
  ui_story_5058_50581002_47_dialog_content = "Posso te levar ao novo parque de diversões!",
  ui_story_5058_50581002_48_dialog_content = "Parque de diversões! Posso ir? Papai e irmão vão conosco também?",
  ui_story_5058_50581002_49_dialog_content = "Sim. Podemos ir primeiro já que o papai está no exterior a trabalho e seu irmão está na escola. Podemos ir todos juntos várias vezes quando eles voltarem.",
  ui_story_5058_50581002_50_dialog_content = "Posso administrar um negócio como o papai?",
  ui_story_5058_50581002_51_dialog_content = "Isso é muito arriscado para você, querido(a). Passei por muita coisa e sofri muito para chegar onde estou agora.",
  ui_story_5058_50581002_52_dialog_content = "Então eu não quero que meu bebê passe pelas mesmas coisas...",
  ui_story_5058_50581002_53_dialog_content = "Tá bom... Ei, estou curioso sobre aquela coisa divertida bem ali...",
  ui_story_5058_50581002_54_dialog_content = "Abaixe o ritmo, bebê.",
  ui_story_5058_50581002_55_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5058_50581002_56_dialog_content = "Meu guarda-chuva foi levado pelo vento...",
  ui_story_5058_50581002_57_dialog_content = "Está tudo bem, mãe! Veja, eu encontrei um lindo guarda-chuva que é ainda maior que o seu!",
  ui_story_5058_50581002_58_dialog_content = "Eu também posso segurar isso para você!",
  ui_story_5058_50581002_59_dialog_content = "Suspirar...",
  ui_story_5058_50581002_60_dialog_content = "A chuva está prestes a parar. Eu quero ir lá!",
  ui_story_5058_50581002_61_dialog_content = "Onde você está, meu bebê?",
  ui_story_5058_50581002_62_dialog_content = "Precioso? Laurie!<size=45>Lorelei!</size>",
  ui_story_5058_50581002_63_dialog_content = "Não me deixe... Não me abandone...",
  ui_story_5058_50581002_64_dialog_content = "Espere, como foi que eu disse isso?",
  ui_story_5058_50581002_65_dialog_content = "Entendi, é porque eu não consigo ficar longe de você...",
  ui_story_5058_50581002_66_dialog_content = "Sou eu quem precisava de você por perto...",
  ui_story_5058_50581101_1_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5058_50581101_2_dialog_content = "Ok, o sistema de ventilação está funcionando.",
  ui_story_5058_50581101_3_dialog_content = "Mas por que aquela porta está aberta?",
  ui_story_5058_50581101_4_dialog_content = "Não costuma estar fechado?",
  ui_story_5058_50581101_5_dialog_content = "Há um porão aqui apenas para ar-condicionados.",
  ui_story_5058_50581101_6_dialog_content = "Você guarda ar-condicionados no subterrâneo?",
  ui_story_5058_50581101_7_dialog_content = "Apenas o sistema principal. Os canos se conectam ao exterior.",
  ui_story_5058_50581101_8_dialog_content = "Porque ocupa muito espaço e é muito barulhento, eu estava tentando descobrir exatamente onde colocá-lo mesmo antes de construir o hotel.",
  ui_story_5058_50581101_9_dialog_content = "Até que Cena sugeriu cavar um porão para isso. Isso também é de sua jurisdição.",
  ui_story_5058_50581101_10_dialog_content = "Não conseguimos encontrar Cena e Shashona de jeito nenhum. Será que eles estão no porão?",
  ui_story_5058_50581101_11_dialog_content = "Chefe, PlayerName... Por que todos estão fora?",
  ui_story_5058_50581101_12_dialog_content = "Bopper? Você está acordado!",
  ui_story_5058_50581101_13_dialog_content = "Mas eles ainda estão...",
  ui_story_5058_50581101_14_dialog_content = "Por favor, vá acordar todo mundo, Bopper, e depois verifique os convidados.",
  ui_story_5058_50581101_15_dialog_content = "PlayerName e eu iremos até o porão para ver se Cena está lá embaixo.",
  ui_story_5058_50581101_16_dialog_content = "Claro!",
  ui_story_5058_50581101_17_dialog_content = "Hmm, acho que ouvi passos no porão. É o Sr. Cena?",
  ui_story_5058_50581101_18_dialog_content = "Pode ser?",
  ui_story_5058_50581101_19_dialog_content = "<color=#e8d9bb>Tum, tum, tum!</color>",
  ui_story_5058_50581101_20_dialog_content = "Graagh!",
  ui_story_5058_50581102_1_dialog_content = "<size=45>Cena? Mãmãe? Você tá aí?</size>",
  ui_story_5058_50581102_2_dialog_content = "Você está aí...?",
  ui_story_5058_50581102_X2_dialog_content = "Você tá aí?",
  ui_story_5058_50581102_X3_dialog_content = "... Não é?",
  ui_story_5058_50581102_3_dialog_content = "Não é de admirar que os Eclipsitas pudessem entrar no hotel. Isso é claramente um túnel e quem sabe onde ele leva.",
  ui_story_5058_50581102_4_dialog_content = "Quando saí do porão para Cena, nunca imaginei que ele cavaria um túnel às minhas costas.",
  ui_story_5058_50581102_5_dialog_content = "Vejo muitas mesas, cadeiras, garrafas e latas por aqui, mas parecem ser muito antigas.",
  ui_story_5058_50581102_6_dialog_content = "Muito velho? Não me diga que...",
  ui_story_5058_50581102_7_dialog_content = "É aquela uma pilha de arquivos embaixo do banquinho?",
  ui_story_5058_50581102_8_dialog_content = "Vejamos...",
  ui_story_5058_50581102_9_dialog_content = "\"Fórmula para Incenso Denuo?\"",
  ui_story_5058_50581102_10_dialog_content = "Eu só falei com Cena sobre isso esta manhã, mas ele já estava pesquisando antes, ou...",
  ui_story_5058_50581102_11_dialog_content = "Diz que o componente mais importante para o incenso é a... <color=#FFB400>Deusa Denuo</color>?!",
  ui_story_5058_50581102_12_dialog_content = "O quê?!",
  ui_story_5058_50581102_13_dialog_content = "E os documentos pertenciam a... Vila Denuo.",
  ui_story_5058_50581102_14_dialog_content = "Este é o vestígio da Vila Denuo? Mas eu não sabia que os aldeões costumavam fazer incenso com as Deusas Denuo.",
  ui_story_5058_50581102_15_dialog_content = "De jeito nenhum Cena não sabia disso, mas como ele nunca me contou?",
  ui_story_5058_50581102_16_dialog_content = "Você e Cena são da vila?",
  ui_story_5058_50581102_17_dialog_content = "Desculpe, acabei pegando um pedaço do seu sonho quando tentei te acordar.",
  ui_story_5058_50581102_18_dialog_content = "Então, acho que você também descobriu que Shashona não é minha mãe biológica.",
  ui_story_5058_50581102_19_dialog_content = "Mas tudo bem, PlayerName, eu não quis esconder meu passado.",
  ui_story_5058_50581102_20_dialog_content = "Apenas estou preocupado que mencionar isso possa fazer minha mãe Shashona se sentir mal.",
  ui_story_5058_50581102_21_dialog_content = "E você viu como ela é boa para mim também, e fez muito por mim, então eu não deveria estar me apegando ao passado como estou agora.",
  ui_story_5058_50581102_22_dialog_content = "Mas essas lembranças, felizes ou tristes, ainda aparecem de vez em quando.",
  ui_story_5058_50581102_23_dialog_content = "Então, você conhecia o Cena desde muito tempo atrás?",
  ui_story_5058_50581102_24_dialog_content = "Ele era nosso vizinho. Eu o chamava de Sr. Cena.",
  ui_story_5058_50581102_25_dialog_content = "Um dia, uma tempestade de areia sem precedentes atingiu Denuo. Eu vi com meus próprios olhos a destruição de toda a aldeia.",
  ui_story_5058_50581102_26_dialog_content = "Eu me machuquei no desastre, mas lembro que foi Cena quem me salvou.",
  ui_story_5058_50581102_27_dialog_content = "E também vagamente como ele me entregou à minha mãe adotiva...",
  ui_story_5058_50581102_28_dialog_content = "Eu pensei que ele arranjaria tempo para me ver, mas ele nunca fez isso até um encontro casual logo antes de construir o resort.",
  ui_story_5058_50581102_29_dialog_content = "Na verdade, quando desmaiei no vale antes, vi o rosto do jovem Cena em um sonho por algum motivo.",
  ui_story_5058_50581102_30_dialog_content = "O túnel subterrâneo, o incenso Denuo, as Eclipsitas, aquela coisa estranha no ar e a Deusa Denuo...",
  ui_story_5058_50581102_31_dialog_content = "Cena é a chave para tudo isso.",
  ui_story_5058_50581102_32_dialog_content = "O tempo o transformou em alguém que eu não reconheço totalmente.",
  ui_story_5058_50581102_33_dialog_content = "Mas ainda estou disposto a confiar nele, no irmão mais velho que me salvou no desastre.",
  ui_story_5058_50581102_34_dialog_content = "O que ele está fazendo, no entanto?",
  ui_story_5058_50581102_35_dialog_content = "<color=#e8d9bb>Tum, tum, tum...</color>",
  ui_story_5058_50581102_36_dialog_content = "Quem está aí? É um Eclipsita?",
  ui_story_5058_50581102_37_dialog_content = "Sou eu...",
  ui_story_5058_50581102_38_dialog_content = "Cena.",
  ui_story_5058_50581201_1_dialog_content = "Suspiro, você descobriu este lugar.",
  ui_story_5058_50581201_2_dialog_content = "Você leu os arquivos, entendo...",
  ui_story_5058_50581201_3_dialog_content = "Tenho muitas perguntas para você.",
  ui_story_5058_50581201_4_dialog_content = "Espere, o Cena está carregando alguém nas costas?",
  ui_story_5058_50581201_X4_dialog_content = "... É Shashona!",
  ui_story_5058_50581201_5_dialog_content = "Mãe?!",
  ui_story_5058_50581201_6_dialog_content = "O que você fez com minha mãe, Cena?!",
  ui_story_5058_50581201_7_dialog_content = "Eu...",
  ui_story_5058_50581201_8_dialog_content = "Graah!!",
  ui_story_5058_50581201_9_dialog_content = "Heh, eles ainda alcançaram.",
  ui_story_5058_50581201_10_dialog_content = "Vamos nos livrar das Eclipsitas primeiro, Lorelei!",
  ui_story_5058_50581202_1_dialog_content = "Bopper disse que você e Lorelei desceram para o porão, mas nunca voltaram, PlayerName. Carleen e eu estávamos prestes a ir verificar vocês!",
  ui_story_5058_50581202_2_dialog_content = "Há algum outro Eclipsita lá em baixo? Tudo bem?",
  ui_story_5058_50581202_3_dialog_content = "Ah, Vice, Carleen... Graças a Deus você acordou.",
  ui_story_5058_50581202_4_dialog_content = "Há uma passagem para o coração do vale no porão, mas nós a selamos, então não deve haver mais Eclipsita.",
  ui_story_5058_50581202_5_dialog_content = "Uma passagem no porão...?",
  ui_story_5058_50581202_6_dialog_content = "Como estão os convidados, Bopper?",
  ui_story_5058_50581202_7_dialog_content = "Todos acordaram do coma, mas... alguns deles estão pedindo aquela coisa no ar.",
  ui_story_5058_50581202_8_dialog_content = "Eles disseram que se sentiram bem após inalar e queriam entrar no mesmo coma de novo!",
  ui_story_5058_50581202_9_dialog_content = "É exatamente o que eu sinto. Pode ser um coma, mas acordei incrivelmente revigorado.",
  ui_story_5058_50581202_10_dialog_content = "Eu também! Meu corpo se sentia leve e fofo como se eu estivesse voando...",
  ui_story_5058_50581202_11_dialog_content = "Se eu estiver correto, aquela coisa provavelmente tem uma conexão com a Deusa Denuo.",
  ui_story_5058_50581202_12_dialog_content = "Ou devo dizer a você... Cena?",
  ui_story_5058_50581202_13_dialog_content = "...",
  ui_story_5058_50581202_14_dialog_content = "Gerente geral Cena?! Estávamos procurando você por toda parte! Você estava no porão também?",
  ui_story_5058_50581202_15_dialog_content = "Diga aos convidados que não há nada no ar e venda a ideia de que tudo foi uma alucinação, Bopper.",
  ui_story_5058_50581202_16_dialog_content = "O vício vai parar alguns dias depois que chegarem em casa.",
  ui_story_5058_50581202_17_dialog_content = "Aquilo causa vícios?",
  ui_story_5058_50581202_18_dialog_content = "Aff...",
  ui_story_5058_50581202_19_dialog_content = "Shashona? Os Eclipsitas machucaram ela? Vou chamar um doutor agora mesmo...",
  ui_story_5058_50581202_20_dialog_content = "Tudo bem, Bopper. O médico médio não pode ajudar mesmo.",
  ui_story_5058_50581202_21_dialog_content = "Pode me dizer o que aconteceu com minha mãe agora, Cena?",
  ui_story_5058_50581202_22_dialog_content = "Você estava certo, Lorelei, tudo isso aconteceu por minha causa.",
  ui_story_5058_50581202_23_dialog_content = "Fui procurar a Deusa Denuo no vale, mas não percebi que a Sra. Shashona estava me seguindo.",
  ui_story_5058_50581202_24_dialog_content = "Então, nós encontramos a Deusa. Ou mais precisamente, uma Deusa madura.",
  ui_story_5058_50581202_25_dialog_content = "A Deusa Denuo?! A história é verdadeira? Você recebeu alguma bênção?",
  ui_story_5058_50581202_26_dialog_content = "Nunca houve bênçãos ou proteção.",
  ui_story_5058_50581202_X26_dialog_content = "Ela rugiu, bateu as asas e provocou uma tempestade. Se ela deixou algum \"presente\"...",
  ui_story_5058_50581202_27_dialog_content = "É o <color=#FFB400>pó</color> que ela liberou. Muito pó, aliás, o suficiente para entrar no hotel através do corredor subterrâneo.",
  ui_story_5058_50581202_28_dialog_content = "Pó? Você quer dizer aqueles que brilhavam no ar?",
  ui_story_5058_50581202_29_dialog_content = "Sim. O pó é uma substância neurológica que causa coma, alucinação ou recuperação de memória.",
  ui_story_5058_50581202_30_dialog_content = "Eu tive certa imunidade desde a infância, mas não a Sra. Shashona...",
  ui_story_5058_50581202_31_dialog_content = "Ela inalou muito <color=#FFB400>pó</color> tentando me salvar.",
  ui_story_5058_50581202_32_dialog_content = "Mas todo o pó acabou agora, por que minha mãe não está acordando?",
  ui_story_5058_50581202_33_dialog_content = "Você não me acordou com sua habilidade psíquica, PlayerName? Você pode salvar minha mãe, por favor?",
  ui_story_5058_50581202_34_dialog_content = "Claro, vou tentar.",
  ui_story_5058_50581202_35_option_content = "Aumento de Força!",
  ui_story_5058_50581202_36_dialog_content = "<color=#e8d9bb>Pit-patter, pitter-patter...</color>",
  ui_story_5058_50581202_37_dialog_content = "Está chovendo?",
  ui_story_5058_50581202_38_dialog_content = "*Soluço*",
  ui_story_5058_50581202_39_dialog_content = "Onde você está, Shashona?",
  ui_story_5058_50581202_40_dialog_content = "O sonho dela está desmoronando?",
  ui_story_5058_50581202_41_dialog_content = "<size=45>Responda-me, Shashona!</size>",
  ui_story_5058_50581202_42_dialog_content = "*Soluço*",
  ui_story_5058_50581202_43_dialog_content = "De onde vem essa voz?",
  ui_story_5058_50581202_44_dialog_content = "Tão frio... Se isso continuar...",
  ui_story_5058_50581202_45_dialog_content = "Vou ser...",
  ui_story_5058_50581202_46_dialog_content = "<color=#e8d9bb>Tapa!</color>",
  ui_story_5058_50581202_47_dialog_content = "Que diabos...",
  ui_story_5058_50581202_48_dialog_content = "Está tudo bem, ele voltou.",
  ui_story_5058_50581202_49_dialog_content = "Ah, meu rosto... Isso doeu.",
  ui_story_5058_50581202_50_dialog_content = "Pare de nos assustar assim, PlayerName. Não conseguimos obter uma resposta sua!",
  ui_story_5058_50581202_51_dialog_content = "Então tive que recorrer a dar tapas. Felizmente, funcionou.",
  ui_story_5058_50581202_52_dialog_content = "Então, como é?",
  ui_story_5058_50581202_53_dialog_content = "O sonho dela estava desmoronando e eu não conseguia encontrá-la de jeito nenhum... Desculpe.",
  ui_story_5058_50581202_54_dialog_content = "Acho que ela inalou mais pó do que eu pensava.",
  ui_story_5058_50581202_55_dialog_content = "Não me assuste assim, mãe... Acorde!",
  ui_story_5058_50581202_56_dialog_content = "Ainda não saímos no nosso próprio parque e há muitas outras coisas para fazer juntos...",
  ui_story_5058_50581202_57_dialog_content = "Por que você insistiu em encontrar a Deusa Denuo, Cena?",
  ui_story_5058_50581202_58_dialog_content = "O túnel no porão e os arquivos estranhos... Acredito que você deve Lorelei uma explicação.",
  ui_story_5058_50581202_59_dialog_content = "Havia algumas coisas que eu nunca tive a chance de te dizer antes, Lorelei.",
  ui_story_5058_50581202_60_dialog_content = "Porque você ainda era muito jovem para entendê-los naquela época.",
  ui_story_5058_50581202_61_dialog_content = "EveAté hoje, eu lutei com a decisão de revelar a verdade para você.",
  ui_story_5058_50581202_62_dialog_content = "Quando vi o quanto você estava animado para reconstruir o vale...",
  ui_story_5058_50581202_63_dialog_content = "Bem, eu realmente pensei que talvez pudesse finalmente esquecer tudo sobre o passado e começar de novo, mas eu estava errado.",
  ui_story_5058_50581202_64_dialog_content = "A Deusa Denuo voltou.",
  ui_story_5058_50581202_65_dialog_content = "Voltou para <color=#FFB400>vingança</color>.",
  ui_story_5058_50581301_1_dialog_content = "Neste vale, uma vez existiu uma pequena vila autossuficiente.",
  ui_story_5058_50581301_2_dialog_content = "Por gerações, os moradores da vila acreditavam que a <color=#FFB400>Deusa Denuo</color> era sua divindade protetora, protegendo o desfiladeiro dos Eclipsitas.",
  ui_story_5058_50581301_3_dialog_content = "Dizia-se que as pessoas que viam a Deusa receberiam suas bênçãos e proteção.",
  ui_story_5058_50581301_4_dialog_content = "No entanto, ninguém podia ter certeza de que a Deusa era real. Eveventualmente, alguns aldeões zombaram da ideia.",
  ui_story_5058_50581301_5_dialog_content = "Muitos começaram a ignorar o aviso da Deusa na história e a explorar os recursos do vale, começando pelos minerais, depois pelas plantas e até mesmo...",
  ui_story_5058_50581301_6_dialog_content = "Você salvou uma Deusa Denuo?",
  ui_story_5058_50581301_7_dialog_content = "Era tão bonito quanto um diamante, como nas histórias? Onde você viu isso?",
  ui_story_5058_50581301_8_dialog_content = "Como você pergunta, pai?",
  ui_story_5058_50581301_9_dialog_content = "Se a Deusa Denuo realmente existe, temos que aproveitar isso, é claro.",
  ui_story_5058_50581301_10_dialog_content = "De jeito nenhum, a Deusa é nossa divindade padroeira!",
  ui_story_5058_50581301_11_dialog_content = "Por que, seu moleque! Como ousa sua bunda preguiçosa me responder! Você acha que tudo que você tem simplesmente caiu do céu?",
  ui_story_5058_50581301_12_dialog_content = "Posso cuidar de mim mesma muito bem agora, obrigada!",
  ui_story_5058_50581301_13_dialog_content = "Tudo bem, saia da minha vista!",
  ui_story_5058_50581301_14_dialog_content = "Eu saí de casa e fui acolhido por Coco, a mãe biológica de Lorelei. Mas, para minha surpresa, meu pai e outros ainda descobriram onde a Deusa está escondida, encontrando posteriormente muitas borboletas bebês...",
  ui_story_5058_50581301_15_dialog_content = "Eles queriam fazer amostras para vender aos ricos em Umbraton e Lumópolis, apenas para descobrir acidentalmente que o pó da Deusa poderia induzir um coma confortável.",
  ui_story_5058_50581301_16_dialog_content = "Então eles usam isso para fazer incenso viciante.",
  ui_story_5058_50581301_17_dialog_content = "O Incenso Denuo...",
  ui_story_5058_50581301_18_dialog_content = "Correto. O incenso se tornou um sucesso instantâneo e mais vendido em todo o Astra.",
  ui_story_5058_50581301_19_dialog_content = "Embora o processo de produção exigisse o sacrifício da Deusa Denuo e a fumaça excessiva do incenso causasse danos neurológicos irreversíveis, os aldeões ainda caçavam as borboletas como se estivessem possuídos.",
  ui_story_5058_50581301_20_dialog_content = "Denuo prosperou e, para evitar que estranhos roubassem a fórmula, os moradores cavaram um túnel subterrâneo.",
  ui_story_5058_50581301_21_dialog_content = "É a passagem no fundo do porão!",
  ui_story_5058_50581301_22_dialog_content = "O túnel conectava a oficina da vila ao coração do vale para facilitar as expedições de borboletas. Mas ninguém esperava...",
  ui_story_5058_50581301_23_dialog_content = "Por favor, todos, deixem a Deusa Denuo em paz!",
  ui_story_5058_50581301_24_dialog_content = "Nunca houve um Eclipsita na história de Denuo, mas agora...?",
  ui_story_5058_50581301_25_dialog_content = "Recebemos enxames deles todos os dias.",
  ui_story_5058_50581301_26_dialog_content = "É um aviso da Deusa Denuo! Estamos tirando tanto do vale que estamos até de olho na nossa divindade protetora!",
  ui_story_5058_50581301_27_dialog_content = "Haha, hahaha!",
  ui_story_5058_50581301_28_dialog_content = "Alguém ainda acredita que a Deusa Denuo é nossa divindade protetora? Estou rindo muito.",
  ui_story_5058_50581301_29_dialog_content = "Uma palavra de conselho, a borboleta não pode proteger o desfiladeiro, já que nem consegue se proteger!",
  ui_story_5058_50581301_30_dialog_content = "A única coisa boa que eles fazem é o pó que soltam quando estão assustados.",
  ui_story_5058_50581301_31_dialog_content = "Os Eclipsitas são atraídos aqui pela poderosa Lúmina no pó.",
  ui_story_5058_50581301_32_dialog_content = "Não tenha medo. Já compramos as armas mais avançadas com o dinheiro que conseguimos. Vai ser fácil eliminar os Eclipsitas.",
  ui_story_5058_50581301_33_dialog_content = "Você deveria nos agradecer por nos livrarmos dos Eclispites e manter a paz para alguém que está fora de sintonia com o tempo como você!",
  ui_story_5058_50581301_34_dialog_content = "Eu não preciso da sua proteção...",
  ui_story_5058_50581301_35_dialog_content = "E por favor, pare de destruir as mudas que plantei no vale!",
  ui_story_5058_50581301_36_dialog_content = "Espere, ela disse que plantou árvores? Que piada...",
  ui_story_5058_50581301_37_dialog_content = "Só me lembro de como minha mãe trabalhava duro para ganhar a vida.",
  ui_story_5058_50581301_38_dialog_content = "Eu nunca soube que ela estava plantando árvores para o desfiladeiro gradualmente árido desde aquela época!",
  ui_story_5058_50581301_39_dialog_content = "Mas se Coco soubesse que, décadas depois, sua filha Lorelei trouxe vida de volta ao vale, ela ficaria orgulhosa e extasiada.",
  ui_story_5058_50581301_40_dialog_content = "Uma pena que os moradores acharam que ela era tola por não pegar o dinheiro na época...",
  ui_story_5058_50581301_41_dialog_content = "Eles não sabiam que uma Deusa furiosa estava prestes a desencadear a destruição sobre Denuo.",
  ui_story_5058_50581301_42_dialog_content = "Naquele dia, eu me esgueirei até onde os aldeões guardavam a Deusa Denuo, apenas para ver que todas as borboletas haviam desaparecido...",
  ui_story_5058_50581301_43_dialog_content = "As borboletas bebês que eles mantinham se foram, Coco...",
  ui_story_5058_50581301_44_dialog_content = "Quem na vila faria uma coisa dessas além de você e eu?",
  ui_story_5058_50581301_45_dialog_content = "<color=#e8d9bb>Uau, uau...</color>",
  ui_story_5058_50581301_46_dialog_content = "Isso é estranho. Geralmente não é ventoso por volta desta hora...",
  ui_story_5058_50581301_47_dialog_content = "Você também vê algo no vento, Cena?",
  ui_story_5058_50581301_48_dialog_content = "Pó?",
  ui_story_5058_50581301_49_dialog_content = "?!",
  ui_story_5058_50581301_50_dialog_content = "É a Deusa Denuo... Ela está furiosa ao perceber que seus filhos foram assassinados!",
  ui_story_5058_50581301_51_dialog_content = "Esse vento não vai parar. Temos que correr por nossas vidas, Cena, agora!",
  ui_story_5058_50581301_52_dialog_content = "Ah não, Lorelei ainda está em casa...",
  ui_story_5058_50581301_53_dialog_content = "Voltamos para pegar o Lorelei para que pudéssemos sair do vale por um caminho marcado com uma vegetação esparsa.",
  ui_story_5058_50581301_54_dialog_content = "Mas no caminho, eu não percebi um enorme pedregulho balançando acima...",
  ui_story_5058_50581301_55_dialog_content = "Coco me empurrou para fora do caminho apenas para ser esmagada pela rocha.",
  ui_story_5058_50581301_56_dialog_content = "Por que você me salvou? Pessoas como eu não valem o esforço...",
  ui_story_5058_50581301_57_dialog_content = "Jovem tolo... Tosse... Sempre te considerei como família.",
  ui_story_5058_50581301_58_dialog_content = "Por favor, aguente firme, Coco. Vou encontrar algo para mover a pedra de cima de você!",
  ui_story_5058_50581301_59_dialog_content = "Eu estou acabado... Even mesmo que você mova a pedra, tosse... Ainda não consigo andar ou sair.",
  ui_story_5058_50581301_60_dialog_content = "Obrigado, Cena... por me ajudar todos esses anos. Tosse... Tenho um último favor para lhe pedir...",
  ui_story_5058_50581301_61_dialog_content = "Correr... Pegue Lorelei e... correr...!",
  ui_story_5058_50581301_62_dialog_content = "Lorelei... Lorelei?!",
  ui_story_5058_50581301_63_dialog_content = "Foi quando percebi que o jovem Lorelei tinha sido derrubado no chão e desmaiado.",
  ui_story_5058_50581301_64_dialog_content = "Peguei Lorelei, mas antes de sair, me virei para Coco apenas para ver...",
  ui_story_5058_50581301_65_dialog_content = "A cor vai desaparecendo lentamente do rosto dela sob a pesada rocha.",
  ui_story_5058_50581301_66_dialog_content = "Impotência, remorso, culpa... Tantas emoções me inundaram de uma vez só. Acreditei que era tudo um castigo da Deusa Denuo para os aldeões.",
  ui_story_5058_50581301_67_dialog_content = "E eu era o mais merecedor de punição. Se eu não tivesse encontrado a jovem Deusa, nada disso teria acontecido.",
  ui_story_5058_50581301_68_dialog_content = "Justo quando eu estava prestes a desistir e aceitar minha morte na tempestade de areia, eu olhei para Lorelei e lembrei do último desejo de Coco.",
  ui_story_5058_50581301_69_dialog_content = "Para Coco, para Lorelei, eu preciso escapar...",
  ui_story_5058_50581301_70_dialog_content = "A tempestade de areia destruiu completamente Denuo. Quase ninguém sobreviveu além de mim e Lorelei.",
  ui_story_5058_50581301_71_dialog_content = "Mas então você me entregou para Shashona, minha nova mãe.",
  ui_story_5058_50581301_72_dialog_content = "Ela já era extremamente rica. Além disso, ela realmente gostava de você, prometeu te curar até que você recuperasse a saúde e te tratar como se fosse da família.",
  ui_story_5058_50581301_73_dialog_content = "Isso é muito melhor do que ficar com um vagabundo sem dinheiro como eu.",
  ui_story_5058_50581301_74_dialog_content = "Sem falar que ela cumpriu sua palavra.",
  ui_story_5058_50581301_75_dialog_content = "Então quem libertou as borboletas bebês no dia daquela tempestade de areia?",
  ui_story_5058_50581301_76_dialog_content = "A mãe deles. Quem mais poderia ser?",
  ui_story_5058_50581301_77_dialog_content = "A Deusa Denuo libertou seus filhos antes de punir a aldeia!",
  ui_story_5058_50581301_78_dialog_content = "Então, ela não só deixou de proteger as pessoas, como também se virou e as puniu?",
  ui_story_5058_50581301_79_dialog_content = "Por que você não me disse isso desde o começo?",
  ui_story_5058_50581301_80_dialog_content = "Você ainda era muito jovem naquela época. Coco também não queria que você soubesse.",
  ui_story_5058_50581301_81_dialog_content = "E agora? Você sabia a verdade e mesmo assim concordou em usar a Deusa como um truque para promover o parque!",
  ui_story_5058_50581301_82_dialog_content = "Por que você nos deixaria ir encontrar a borboleta no vale?",
  ui_story_5058_50581301_83_dialog_content = "Por que você me diria que faria o Incenso Denuo que a diretoria queria?",
  ui_story_5058_50581301_84_dialog_content = "Você está tentando repetir aquela tragédia de novo?",
  ui_story_5058_50581301_85_dialog_content = "Ou você está realmente ansioso pelo chamado castigo da Deusa e planejou tudo?",
  ui_story_5058_50581301_86_dialog_content = "Bem, como devo responder a tudo isso?",
  ui_story_5058_50581301_87_dialog_content = "Mayseja sim, talvez não...",
  ui_story_5058_50581301_88_dialog_content = "Desde que te dei para a Sra. Shashona, tenho vagado pela Astra...",
  ui_story_5058_50581301_X88_dialog_content = "Depois de tudo que passei, ainda não consegui tirar a tempestade de areia da minha cabeça.",
  ui_story_5058_50581301_89_dialog_content = "Mayeu deveria ter morrido ali mesmo, não vivendo como um covarde.",
  ui_story_5058_50581301_90_dialog_content = "Então...|Eu voltei.",
  ui_story_5058_50581301_X90_dialog_content = "Embora mais de dez anos tivessem se passado, eu finalmente tive coragem de retornar e enfrentar o julgamento da Deusa Denuo.",
  ui_story_5058_50581301_91_dialog_content = "Mas quando cheguei, descobri que o Vale Denuo já havia se tornado um deserto, e a Deusa Denuo não estava em lugar nenhum.",
  ui_story_5058_50581301_92_dialog_content = "Justo quando eu estava pensando em desistir de tudo, descobri que alguém realmente começou a reconstruir o Vale Denuo!",
  ui_story_5058_50581301_93_dialog_content = "Naquele momento, eu não sabia de nada. Eu só não queria ver o único lar que eu conhecia se tornar um deserto.",
  ui_story_5058_50581301_94_dialog_content = "Foi naquele instante que eu vi Coco, vivendo através de você. Eu sei que se ela estivesse lá, teria feito exatamente a mesma coisa...",
  ui_story_5058_50581301_95_dialog_content = "A Vila Denuo já havia sido punida por abandonar sua fé, e o vale foi devastado como resultado.",
  ui_story_5058_50581301_96_dialog_content = "Mas, considerando que a Deusa Denuo parecia ter desaparecido do vale, será que sua punição já havia cumprido seu curso?",
  ui_story_5058_50581301_97_dialog_content = "Mayseja... Mayseja após reconstruir o vale, tudo voltará ao que era antes - antes da Deusa Denuo ter sido desprezada.",
  ui_story_5058_50581301_98_dialog_content = "Então, fiz minha escolha. Escolhi viver... para ajudar você a restaurar o vale à sua antiga glória...",
  ui_story_5058_50581301_99_dialog_content = "Eu queria testemunhar o glorioso renascimento do vale com meus próprios olhos!",
  ui_story_5058_50581301_100_dialog_content = "Você está esquecendo do túnel subterrâneo...",
  ui_story_5058_50581301_101_dialog_content = "Eu pensei que cada último vestígio da Vila Denuo tivesse sido varrido no tempestade de areia.",
  ui_story_5058_50581301_102_dialog_content = "Anos depois, descobri que o túnel que os aldeões usaram para capturar a Deusa Denuo ainda estava intacto.",
  ui_story_5058_50581301_103_dialog_content = "Encontrei-me diante de um dilema. Eu considerei incendiar toda a caverna e enterrá-la para sempre...",
  ui_story_5058_50581301_104_dialog_content = "Mas a Vila Denuo é minha casa. Como eu poderia me convencer a destruir o último vestígio do meu povo?",
  ui_story_5058_50581301_105_dialog_content = "Acho que talvez, um dia, eu deixe a verdade sobre o que aconteceu com a vila em suas mãos, Lorelei. Você pode decidir por si mesmo o que acontece com as ruínas lá embaixo.",
  ui_story_5058_50581301_106_dialog_content = "Eu só nunca esperava que este dia chegasse tão cedo! Acho que eu não imaginava que a Deusa Denuo ainda guardaria um rancor tão duradouro contra os aldeões...",
  ui_story_5058_50581301_107_dialog_content = "Ela voltou para obter vingança! Voltou para me punir, o pecador que escapou de uma morte cruel sob as areias!",
  ui_story_5058_50581301_108_dialog_content = "Chega! Cena, você está levando isso tudo muito a sério.",
  ui_story_5058_50581301_109_dialog_content = "Vingança, pecado... Essas ideias selvagens são apenas produtos de uma mente hiperativa.",
  ui_story_5058_50581301_110_dialog_content = "Even mesmo que as Deusas Denuo possuam algum poder místico, não é o tipo que pode causar uma tempestade de areia capaz de destruir uma vila inteira.",
  ui_story_5058_50581301_111_dialog_content = "Maytalvez não seja algum tipo de punição divina, mas mais como os moradores de Denuo colhendo o que plantaram.",
  ui_story_5058_50581301_112_dialog_content = "Os animais e plantas do vale criaram um santuário para os habitantes desta terra árida, mas quando esse equilíbrio foi quebrado, era natural que seu abrigo desaparecesse.",
  ui_story_5058_50581301_113_dialog_content = "Lorelei, acredite ou não... Eu decidi ir atrás da Deusa Denuo e finalmente aceitar a punição que me é devida.",
  ui_story_5058_50581301_114_dialog_content = "Se o que você está dizendo é verdade... não deveria eu aceitar algum tipo de punição? Quer dizer, eu também fazia parte da Vila Denuo naquela época.",
  ui_story_5058_50581301_115_dialog_content = "Você não teve nada a ver com tudo isso. Você era apenas uma criança naquela época, nem sabia o que estava acontecendo.",
  ui_story_5058_50581301_116_dialog_content = "E... E eu prometi ao Coco que faria de tudo para garantir que você tenha uma vida longa e feliz!",
  ui_story_5058_50581301_117_dialog_content = "Feliz? Como posso estar feliz quando minha mãe está em coma!",
  ui_story_5058_50581301_118_dialog_content = "Eu não esperava que algo tão sério acontecesse com Shashona, mas é verdade que alguns foram conhecidos por entrar em um estado vegetativo persistente após inalar quantidades excessivas de Incenso Denuo.",
  ui_story_5058_50581301_119_dialog_content = "O quê?!",
  ui_story_5058_50581301_120_dialog_content = "Mas eu lembro... há um antídoto que pode neutralizar o veneno nas escamas da Deusa Denuo, embora seja bastante difícil de encontrar.",
  ui_story_5058_50581301_121_dialog_content = "Eu não me importo o quão difícil seja! Por favor, apenas me diga como conseguir isso!",
  ui_story_5058_50581301_122_dialog_content = "Bem, é um tipo de muco.",
  ui_story_5058_50581301_123_dialog_content = "Para ser preciso, é o muco que a Deusa Denuo produz ao produzir ovos.",
  ui_story_5058_50581401_1_dialog_content = "<color=#e8d9bb>*Crowd murmurando*</color>",
  ui_story_5058_50581401_2_dialog_content = "O que está acontecendo? Parece que temos clientes insatisfeitos em nossas mãos...",
  ui_story_5058_50581401_3_dialog_content = "Chefe, são os funcionários...",
  ui_story_5058_50581401_4_dialog_content = "EveTodo mundo ouviu a história agora sobre a Deusa Denuo vindo se vingar, e todos estão aterrorizados. Um monte deles quer desistir e sair daqui!",
  ui_story_5058_50581401_5_dialog_content = "Ai...",
  ui_story_5058_50581401_6_dialog_content = "Chefe, toda essa situação precisa ser resolvida agora mesmo... Que tal fecharmos o resort por um tempo, sabe, pela segurança dos funcionários e dos hóspedes...?",
  ui_story_5058_50581401_7_dialog_content = "Feche o resort e nos deixe ir, chefe!",
  ui_story_5058_50581401_8_dialog_content = "Não devemos sofrer a ira da Deusa Denuo!",
  ui_story_5058_50581401_9_dialog_content = "EveTodos, por favor, acalmem-se por um momento.",
  ui_story_5058_50581401_10_dialog_content = "Encerre por aqui, chefe!",
  ui_story_5058_50581401_11_dialog_content = "Vamos para casa! Vamos sair!",
  ui_story_5058_50581401_12_dialog_content = "Meus próprios funcionários... nem mesmo confiam em mim mais.",
  ui_story_5058_50581401_13_dialog_content = "Todos vão simplesmente virar as costas para mim?",
  ui_story_5058_50581401_14_dialog_content = "Finalmente cheguei até aqui, mas nunca pensei que algo assim aconteceria... e tudo por causa da minha própria imprudência...",
  ui_story_5058_50581401_15_dialog_content = "Talvez eu devesse ter ouvido minha mãe desde o começo, em vez de tentar tão arduamente provar meu valor...",
  ui_story_5058_50581401_16_dialog_content = "É tudo culpa minha... Eu ainda não tenho o que é preciso para fazer um negócio como este funcionar...",
  ui_story_5058_50581401_17_dialog_content = "Você não pode pensar assim, Lorelei!",
  ui_story_5058_50581401_18_dialog_content = "Sim, Lorelei! Esse tipo de conversa derrotista não combina com você.",
  ui_story_5058_50581401_19_dialog_content = "Apenas pense em como você conseguiu reconstruir o vale e montar um resort tão magnífico aqui... Obviamente, você é um talento natural para esse tipo de coisa!",
  ui_story_5058_50581401_20_dialog_content = "Concordo plenamente, eu não acho que você precise provar a si mesmo para ninguém!",
  ui_story_5058_50581401_21_dialog_content = "Mas a mamãe nunca teve nada de bom para dizer sobre mim, e agora ela está em coma, e é tudo culpa minha...",
  ui_story_5058_50581401_22_dialog_content = "Tenho certeza de que Shashona sabe o quão incrível você é.",
  ui_story_5058_50581401_23_dialog_content = "Desde o momento em que a conheci, pude perceber o quanto ela estava orgulhosa do seu resort!",
  ui_story_5058_50581401_24_dialog_content = "Mas mãe... ela nunca disse uma palavra boa sobre o resort para mim.",
  ui_story_5058_50581401_25_dialog_content = "Ah, eu nunca teria adivinhado também... Então, descobriu-se que a astuta Sra. Shashona estava fazendo o seu melhor para esconder seus verdadeiros sentimentos de sua filha.",
  ui_story_5058_50581401_26_dialog_content = "Parece que ela simplesmente não estava pronta para—",
  ui_story_5058_50581401_27_dialog_content = "Não! Lorelei...",
  ui_story_5058_50581401_28_dialog_content = "Mãmãe?",
  ui_story_5058_50581401_29_dialog_content = "Não me deixe...",
  ui_story_5058_50581401_30_dialog_content = "Nunca planejei te deixar, Mãe... Você me ouve?",
  ui_story_5058_50581401_31_dialog_content = "...",
  ui_story_5058_50581401_32_dialog_content = "Então, é isso que você temia todo esse tempo?",
  ui_story_5058_50581401_33_dialog_content = "Mãe...",
  ui_story_5058_50581401_34_dialog_content = "Chefe, a equipe... Todos ainda estão esperando por uma resposta...",
  ui_story_5058_50581401_35_dialog_content = "Sim, eu sei.",
  ui_story_5058_50581401_36_dialog_content = "Mãe, eu não vou desistir agora.",
  ui_story_5058_50581401_37_dialog_content = "Não cheguei onde estou hoje por ninguém além de mim mesmo... Tenho meu próprio sonho.",
  ui_story_5058_50581401_38_dialog_content = "Escolhi seguir o caminho mais difícil diante de mim para tornar esse sonho realidade e percebi algo há muito tempo.",
  ui_story_5058_50581401_39_dialog_content = "Não importa quais dificuldades apareçam no meu caminho, eu tenho que enfrentá-las de frente!",
  ui_story_5058_50581401_40_dialog_content = "Não como filha, não como uma empreendedora ingênua, não como uma oportunista aproveitadora...",
  ui_story_5058_50581401_41_dialog_content = "Mas como um chefe com funcionários para liderar e clientes para atender! Um chefe que enfrenta corajosamente e resolve seus problemas!",
  ui_story_5058_50581401_42_dialog_content = "Parece que o Lorelei que conhecemos e amamos está de volta!",
  ui_story_5058_50581401_43_dialog_content = "Obrigado, PlayerName...",
  ui_story_5058_50581401_44_dialog_content = "Funcionários do Denuo Valley Resort! Ouçam!",
  ui_story_5058_50581401_45_dialog_content = "Sei que todos estão com medo agora e devem ter muitas perguntas. Eu falhei em conduzir uma investigação preliminar completa da área e peço desculpas por isso.",
  ui_story_5058_50581401_46_dialog_content = "Então, primeiro, eu só quero dizer... Me desculpem, pessoal!",
  ui_story_5058_50581401_47_dialog_content = "Tornar este resort um sucesso... Bem, é o meu sonho.",
  ui_story_5058_50581401_48_dialog_content = "Foi necessário muito sangue, suor e lágrimas para transformarmos este vale juntos.",
  ui_story_5058_50581401_49_dialog_content = "E por causa disso, o Denuo Valley Resort não é mais apenas o meu sonho.",
  ui_story_5058_50581401_50_dialog_content = "EveCada tijolo deste lugar, cada telha, carrega a marca imortal do trabalho árduo de todos. Este é o nosso sonho compartilhado—esta é a nossa casa!",
  ui_story_5058_50581401_51_dialog_content = "Então, nos deparamos com nosso primeiro obstáculo. Eu não quero fechar o resort e desistir instantaneamente só por causa disso...",
  ui_story_5058_50581401_52_dialog_content = "Não posso virar as costas para o nosso sonho, não vou abandonar a casa que trabalhamos tão duro para construir!",
  ui_story_5058_50581401_53_dialog_content = "Sei que todos estão com medo, sei que estão ansiosos e, para ser sincero, esta é a primeira vez que enfrento um problema como este.",
  ui_story_5058_50581401_54_dialog_content = "Mas quero que todos saibam que estou assumindo o controle da situação e prometo resolver esse assunto o mais rápido possível.",
  ui_story_5058_50581401_55_dialog_content = "Embora o futuro possa ser incerto, por favor, só me dê um pouco mais de tempo... Eu prometo que vou acertar isso!",
  ui_story_5058_50581401_56_dialog_content = "...",
  ui_story_5058_50581401_57_dialog_content = "Já que o chefe colocou dessa forma...",
  ui_story_5058_50581401_58_dialog_content = "Eu realmente quero que minha família visite o resort!",
  ui_story_5058_50581401_59_dialog_content = "E eu quero que meus amigos vejam o incrível lugar onde trabalho...",
  ui_story_5058_50581401_60_dialog_content = "Também espero que vocês possam encontrar a força para retornar às suas funções e continuar atendendo nossos clientes atuais da melhor forma possível.",
  ui_story_5058_50581401_61_dialog_content = "Preciso saber que todos vocês estão comigo! Por favor, me dêem coragem para seguir em frente e cuidar de tudo isso!",
  ui_story_5058_50581401_62_dialog_content = "Acredito que, contanto que trabalhemos juntos, definitivamente superaremos esse pequeno contratempo e colocaremos o resort de volta nos trilhos!",
  ui_story_5058_50581401_63_dialog_content = "Acredito em cada um de vocês... Vocês acreditam em mim?",
  ui_story_5058_50581401_64_dialog_content = "...",
  ui_story_5058_50581401_65_dialog_content = "Chefe, eu... Eu acredito em você!",
  ui_story_5058_50581401_66_dialog_content = "Confiamos em você, Lorelei!",
  ui_story_5058_50581401_67_dialog_content = "Confiar em você, confiar em você, confiar em você!",
  ui_story_5058_50581401_68_dialog_content = "Lorelei... parece mais maduro do que antes, não acha?",
  ui_story_5058_50581401_69_dialog_content = "Acho que ela sempre foi uma empresária bastante madura, mas agora ela tem um pouco mais de força e convicção do que antes.",
  ui_story_5058_50581401_70_dialog_content = "PlayerName, sobre o que vocês dois estão murmurando?",
  ui_story_5058_50581401_71_dialog_content = "Ele estava apenas cantando seus elogios, Lorelei!",
  ui_story_5058_50581401_72_dialog_content = "Hã?",
  ui_story_5058_50581401_73_dialog_content = "Obrigado, PlayerName... Obrigado a todos...",
  ui_story_5058_50581401_74_dialog_content = "Mas agora preciso que todos vocês me deem uma mão.",
  ui_story_5058_50581401_75_dialog_content = "Tudo bem, cuidaremos das Eclipsitas restantes por aqui.",
  ui_story_5058_50581401_76_dialog_content = "E eu também gostaria de entender tudo isso.",
  ui_story_5058_50581401_77_dialog_content = "Quer dizer que...",
  ui_story_5058_50581401_78_dialog_content = "Preciso ir fundo no vale e encontrar a Deusa Denuo, descobrir o que ela quer e... encontrar um antídoto para minha mãe.",
  ui_story_5058_50581401_79_dialog_content = "Parece que estamos indo na mesma direção, então.",
  ui_story_5058_50581401_80_dialog_content = "Venha comigo. Apenas tome cuidado - essa poeira de escamas parece atrair Eclipsitas.",
  ui_story_5058_50581401_81_dialog_content = "Além disso, cubra seu nariz e boca com um pano úmido para não desmaiar antes mesmo de chegarmos lá.",
  ui_story_5058_50581501_1_dialog_content = "Torrente Rápida!",
  ui_story_5058_50581501_2_dialog_content = "Hum...",
  ui_story_5058_50581501_3_dialog_content = "Há tantas Eclipsitas por aqui!",
  ui_story_5058_50581501_4_dialog_content = "Por que a poeira da escala não está afetando os Eclipsitas?",
  ui_story_5058_50581501_5_dialog_content = "Estou adivinhando que é porque a fisiologia deles é diferente da nossa, embora sejam atraídos e fiquem animados com a Lúmina no pó.",
  ui_story_5058_50581501_6_dialog_content = "Está claro onde estão as maiores concentrações de poeira de escala - é onde você encontrará os maiores aglomerados de Eclipsitas...",
  ui_story_5058_50581501_7_dialog_content = "*Rugido*",
  ui_story_5058_50581501_8_dialog_content = "Sai do meu caminho!",
  ui_story_5058_50581501_9_dialog_content = "Parece que quanto mais avançamos, mais poeira de escamas encontramos. Isso significa que estamos nos aproximando da Deusa Denuo?",
  ui_story_5058_50581501_10_dialog_content = "Espere, estou sentindo algo cheio de Lúmina vindo em nossa direção...",
  ui_story_5058_50581501_11_dialog_content = "Mayserá que é um Auroriano vindo para nos ajudar?",
  ui_story_5058_50581501_12_dialog_content = "Mas eu não pedi para mais ninguém vir nos ajudar.",
  ui_story_5058_50581501_13_dialog_content = "Bem, acho que isso deixa apenas uma possibilidade...",
  ui_story_5058_50581501_14_dialog_content = "Está aqui!",
  ui_story_5058_50581501_15_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581501_16_dialog_content = "<size=45>Sss!</size>",
  ui_story_5058_50581501_17_dialog_content = "Hã? É-E com...!",
  ui_story_5058_50581501_18_dialog_content = "É a Deusa Denuo...",
  ui_story_5058_50581501_19_dialog_content = "!!!",
  ui_story_5058_50581501_20_dialog_content = "Mas essa coisa é completamente diferente daquele adesivo fofo da pequena Deusa Denuo!",
  ui_story_5058_50581501_21_dialog_content = "Esse adesivo mostra como essas coisas se parecem quando acabam de nascer. Esta Deusa Denuo flutuando na nossa frente agora é uma <color=#FFB400>rainha borboleta</color> totalmente crescida, pronta para botar seus próprios ovos...",
  ui_story_5058_50581501_22_dialog_content = "<size=45>Chiado, chiado, chiado!</size>",
  ui_story_5058_50581501_23_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581501_24_dialog_content = "EveTodos, encontrem uma planta para se esconderem atrás, para não serem levados pelas asas batendo da Deusa Denuo!",
  ui_story_5058_50581501_25_dialog_content = "Deusa Denuo, as lendas dizem que você possui uma sabedoria incomparável, então com certeza você pode entender o que estou dizendo agora, certo?",
  ui_story_5058_50581501_26_dialog_content = "<size=45>Sss!</size>",
  ui_story_5058_50581501_27_dialog_content = "Cuidado, Lorelei!",
  ui_story_5058_50581501_28_dialog_content = "Hum...",
  ui_story_5058_50581501_29_dialog_content = "Cena?!</translation>",
  ui_story_5058_50581501_30_dialog_content = "Você se lembra de alguém mencionando que a Deusa Denuo ainda era tão forte?",
  ui_story_5058_50581501_31_dialog_content = "Acho que não.",
  ui_story_5058_50581501_32_dialog_content = "*Cof Cof*... Parece que a ira da Deusa Denuo não será tão fácil de acalmar...",
  ui_story_5058_50581501_33_dialog_content = "Saia daqui, rápido. Deixe-me lidar com isso sozinho.",
  ui_story_5058_50581501_34_dialog_content = "Que diabos você está falando!",
  ui_story_5058_50581501_35_dialog_content = "<size=45>Chiado, chiado, chiado!</size>",
  ui_story_5058_50581502_1_dialog_content = "Deusa Denuo, isso é tudo um grande mal-entendido!",
  ui_story_5058_50581502_2_dialog_content = "Não queremos te machucar... Não conseguiríamos mesmo se quiséssemos!",
  ui_story_5058_50581502_3_dialog_content = "<size=45>Chiado, chiado, chiado!</size>",
  ui_story_5058_50581502_4_dialog_content = "Minha mãe está em coma... Ela inalou muito do seu pó de escama, e você é o único que pode—",
  ui_story_5058_50581502_5_dialog_content = "Não adianta...",
  ui_story_5058_50581502_6_dialog_content = "Por quê? Cena, você não consegue se comunicar com insetos? Você sabe o que a Deusa Denuo está dizendo?",
  ui_story_5058_50581502_7_dialog_content = "A Deusa Denuo... ela só fica dizendo \"nunca perdoar, nunca perdoar, nunca perdoar\" repetidamente...",
  ui_story_5058_50581502_8_dialog_content = "!!!",
  ui_story_5058_50581502_9_dialog_content = "Agora todos vocês sabem, ela voltou para se vingar!",
  ui_story_5058_50581502_10_dialog_content = "<size=45>Chiado, chiado, chiado!</size>",
  ui_story_5058_50581502_11_dialog_content = "Hum...",
  ui_story_5058_50581502_12_dialog_content = "Lorelei!!!",
  ui_story_5058_50581502_13_dialog_content = "Você está bem, Lorelei?!",
  ui_story_5058_50581502_14_dialog_content = "*Cof Cof*... Eu... Eu ainda estou aguentando...",
  ui_story_5058_50581502_15_dialog_content = "Se formos forçados a nos esforçar assim por muito mais tempo, receio que as coisas possam tomar um rumo para pior.",
  ui_story_5058_50581502_16_dialog_content = "Vamos lá, Lorelei! Deixe-me ajudá-lo a se levantar!",
  ui_story_5058_50581502_17_dialog_content = "Ei... O que está prestes a cair dessa árvore?",
  ui_story_5058_50581502_18_dialog_content = "Deusa Denuo, se quiser punir alguém, puna apenas a mim!",
  ui_story_5058_50581502_19_dialog_content = "Há mais de dez anos, por acaso, salvei uma Deusa Denuo e fui descuidado o suficiente para deixar toda a aldeia descobrir isso...",
  ui_story_5058_50581502_20_dialog_content = "Silvo...?",
  ui_story_5058_50581502_21_dialog_content = "É isso mesmo, fui eu... Se não fossem as minhas ações, o povo da Vila Denuo nunca teria capturado a Deusa Denuo de forma tão arbitrária...",
  ui_story_5058_50581502_22_dialog_content = "Eu sou aquele que deveria ter enfrentado o castigo divino naquela tempestade de areia! Mas eu fugi em vez disso...",
  ui_story_5058_50581502_23_dialog_content = "Tive que fugir! Alguém muito importante para mim me deu uma missão e eu tinha que concluí-la!",
  ui_story_5058_50581502_24_dialog_content = "Fugi há mais de dez anos e minha alma tem sido atormentada desde então. Estou aqui diante de você buscando redenção!",
  ui_story_5058_50581502_25_dialog_content = "Mas, por favor, deixe-me carregar os pecados do passado sozinho.",
  ui_story_5058_50581502_26_dialog_content = "Isso não tem nada a ver com Lorelei e aqueles outros jovens lá atrás, ou os hóspedes de volta ao resort...",
  ui_story_5058_50581502_27_dialog_content = "Estou disposto a dar minha vida para acertar isso!",
  ui_story_5058_50581502_28_dialog_content = "Por favor, apenas dê a eles o antídoto para o veneno da poeira de escama e deixe-os ir...",
  ui_story_5058_50581502_29_dialog_content = "(Parece que... a Deusa Denuo... se acalmou?)",
  ui_story_5058_50581502_30_dialog_content = "Deusa Denuo, por favor... conceda-me o fim mais doloroso que puder em suas asas mortais...",
  ui_story_5058_50581502_31_dialog_content = "Mayser, eu deveria apenas acabar com minha vida diante dos seus olhos com minha própria arma...",
  ui_story_5058_50581502_32_dialog_content = "O que você está fazendo, Cena?!",
  ui_story_5058_50581502_33_dialog_content = "Percebi quando nos encontramos novamente naquela época como você sempre tenta se apresentar como esse cara maduro que sabe tanto sobre o mundo!",
  ui_story_5058_50581502_34_dialog_content = "A verdade é que você não amadureceu nada! Tudo o que você faz é evitar seus problemas em vez de tentar superá-los!",
  ui_story_5058_50581502_35_dialog_content = "A única coisa pela qual você está vivendo é realmente apenas redenção? Você nem fez nada de errado naquela época!",
  ui_story_5058_50581502_36_dialog_content = "Mãe... Coco te salvou naquela época, e Shashona também te salvou.",
  ui_story_5058_50581502_37_dialog_content = "E o motivo de eles terem feito isso é porque acharam que você valia a pena ser salvo! Mas olhe só para você! Por que insiste em tentar jogar sua vida fora assim?",
  ui_story_5058_50581502_38_dialog_content = "Você quer que as pessoas digam que minhas mães foram duas idiotas que deram suas vidas em vão?!",
  ui_story_5058_50581502_39_dialog_content = "Não... Isso não é...",
  ui_story_5058_50581502_40_dialog_content = "Deusa Denuo, por favor, ouça-me. Tudo o que eu quero fazer é esclarecer esse mal-entendido entre nós!",
  ui_story_5058_50581502_41_dialog_content = "Sibilo?",
  ui_story_5058_50581502_42_dialog_content = "Coco me disse que você concede bênçãos e proteção àqueles que encontra...",
  ui_story_5058_50581502_43_dialog_content = "Acredito no que ela me disse e também acredito que você nunca seria tão cruel a ponto de impor uma forma tão distorcida de suposto castigo divino.",
  ui_story_5058_50581502_44_dialog_content = "Voltei ao Vale Denuo para trazer vida de volta a este lugar! Não cometerei os mesmos erros que os moradores fizeram naquela época!",
  ui_story_5058_50581502_45_dialog_content = "Estou feliz que você também retornou ao Vale Denuo, porque isso significa que tudo o que fiz para restaurar o vale não foi em vão...",
  ui_story_5058_50581502_46_dialog_content = "O fato de você colocar seus ovos no vale novamente é prova suficiente de que eu fiz a diferença!",
  ui_story_5058_50581502_47_dialog_content = "Sss, sss, sss!",
  ui_story_5058_50581502_48_dialog_content = "Deusa Denuo! Eu não quero machucar sua jovem!",
  ui_story_5058_50581502_49_dialog_content = "Eu peguei isso agora mesmo sem saber o que era... Aqui, deixe-me devolver para você!",
  ui_story_5058_50581502_50_dialog_content = "Eu entendo... Você achou que queríamos machucar sua criança, e foi por isso que ficou tão bravo. Não é?",
  ui_story_5058_50581502_51_dialog_content = "Sss, sss, sss, sss!",
  ui_story_5058_50581502_52_dialog_content = "Ela viu... que estávamos carregando redes e tentando capturar seus filhos.",
  ui_story_5058_50581502_53_dialog_content = "Isso é tudo culpa minha! Embora eu tenha nascido no Vale Denuo, eu mal sei alguma coisa sobre você...",
  ui_story_5058_50581502_54_dialog_content = "Eu trouxe todos aqui para o vale... Na verdade, eu esperava que talvez pudesse encontrar uma maneira de ajudar as Deusas Denuo a florescerem aqui mais uma vez...",
  ui_story_5058_50581502_55_dialog_content = "Só agora entendo como foi ingênuo e arrogante da minha parte pensar assim.",
  ui_story_5058_50581502_56_dialog_content = "Este vale é minha casa e o resort é um sonho que muitos de nós prezamos... É por isso que prometo proteger este lugar com mais paixão do que qualquer um!",
  ui_story_5058_50581502_57_dialog_content = "Eu imploro a você—por favor, confie em mim! Eu sei que posso encontrar uma maneira de proteger seu habitat natural e evitar que seus filhotes sejam perturbados!",
  ui_story_5058_50581502_58_dialog_content = "Sibilo?",
  ui_story_5058_50581502_59_dialog_content = "Você quer me perguntar uma coisa?",
  ui_story_5058_50581502_60_dialog_content = "Sim, eu acho que ela é digna de confiança. Sua mãe, Coco, também queria proteger o Vale Denuo e suas borboletas há algum tempo!",
  ui_story_5058_50581502_61_dialog_content = "Acredito que ela herdou os ideais da Coco... É por isso que acredito nela!",
  ui_story_5058_50581502_62_dialog_content = "Sss, sss...",
  ui_story_5058_50581502_63_dialog_content = "A Deusa Denuo não parece mais tão irritada!",
  ui_story_5058_50581502_64_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5058_50581502_65_dialog_content = "Silvo...",
  ui_story_5058_50581502_66_dialog_content = "Hã? Seu filho está prestes a sair do casulo?! O-O que devemos fazer...? Ainda estou segurando-o em minhas mãos!",
  ui_story_5058_50581502_67_dialog_content = "<color=#e8d9bb>A Deusa Denuo pegou o casulo brilhante da mão de Lorelei.</color>",
  ui_story_5058_50581502_68_dialog_content = "Você pode sair agora...",
  ui_story_5058_50581502_69_dialog_content = "Mãe...",
  ui_story_5058_50581502_70_dialog_content = "Muito bem, meu filho. Você cresceu bastante.",
  ui_story_5058_50581502_71_dialog_content = "Eu cresci! Eu quero ser tão grande quanto você, mãe!",
  ui_story_5058_50581502_72_dialog_content = "Óh, e...",
  ui_story_5058_50581502_73_dialog_content = "Eu confio nessa jovem! Se não fosse por ela, eu teria caído da árvore e nunca mais veria mamãe!",
  ui_story_5058_50581502_74_dialog_content = "A pequena borboleta... pousou em Lorelei?!",
  ui_story_5058_50581502_75_dialog_content = "...",
  ui_story_5058_50581502_76_dialog_content = "Então devemos dar a ela nossa mais sincera gratidão.",
  ui_story_5058_50581502_77_dialog_content = "Você quer que eu... estenda minha mão?",
  ui_story_5058_50581502_78_dialog_content = "Hã? Esse é o casulo de onde aquela pequena borboleta saiu agora há pouco?",
  ui_story_5058_50581502_79_dialog_content = "Peço desculpas por incapacitar sua mãe. O fluido dentro do casulo é o antídoto.",
  ui_story_5058_50581502_80_dialog_content = "Nós iremos nos realocar mais fundo no vale. Acredito que você cumprirá sua promessa.",
  ui_story_5058_50581502_81_dialog_content = "Isso é... o muco que o Cena estava falando? Obrigada, Deusa Denuo! Obrigada!",
  ui_story_5058_50581502_82_dialog_content = "Eu prometo que vou cumprir minha palavra!",
  ui_story_5058_50581502_83_dialog_content = "Boa sorte.",
  ui_story_5058_50581502_84_dialog_content = "Lorelei... Você recebeu a bênção da Deusa Denuo?!",
  ui_story_5058_50581502_85_dialog_content = "Você...",
  ui_story_5058_50581502_86_dialog_content = "Oh... Deusa Denuo, Cena tem protegido o vale comigo todo esse tempo! Ele não é tão ruim quanto diz ser...",
  ui_story_5058_50581502_87_dialog_content = "Por favor, não—",
  ui_story_5058_50581502_88_dialog_content = "Hã?",
  ui_story_5058_50581502_89_dialog_content = "<color=#e8d9bb>A Deusa Denuo tocou as asas transparentes nas costas de Cena.</color>",
  ui_story_5058_50581502_90_dialog_content = "Silvo... Eu pareço diferente agora e você também, mas ainda me lembro daquelas asas.",
  ui_story_5058_50581502_91_dialog_content = "Que belo par de asas é esse.",
  ui_story_5058_50581502_92_dialog_content = "Obrigado por me libertar da teia de aranha antes.",
  ui_story_5058_50581502_93_dialog_content = "Foi... Foi você?",
  ui_story_5058_50581502_94_dialog_content = "Aquela tempestade de areia de doze anos atrás não teve nada a ver conosco, e lamento pelo seu sofrimento.",
  ui_story_5058_50581502_95_dialog_content = "Sempre estive procurando por você, não para punir, mas para agradecer.",
  ui_story_5058_50581502_96_dialog_content = "Obrigado por me dar outra vida e que você encontre o propósito da sua.",
  ui_story_5058_50581502_97_dialog_content = "E-Eu vou...",
  ui_story_5058_50581502_98_dialog_content = "Estou ansioso para ver seu filho com asas tão brilhantes quanto as suas.",
  ui_story_5058_50581502_99_dialog_content = "Além de Luke, ninguém nunca apreciou minhas asas dessa forma...",
  ui_story_5058_50581502_100_dialog_content = "É hora de irmos, meu filho.",
  ui_story_5058_50581502_101_dialog_content = "Espere por mim, mãe!",
  ui_story_5058_50581502_102_dialog_content = "Saiu assim, só isso?",
  ui_story_5058_50581502_103_dialog_content = "Hã? Todos os Eclipsitas daqui também foram embora?!",
  ui_story_5058_50581502_104_dialog_content = "Então... acabou tudo agora? EveTudo aconteceu tão de repente, nem tive a chance de processar tudo...",
  ui_story_5058_50581502_105_dialog_content = "Hahahahahahahahaha!",
  ui_story_5058_50581502_106_dialog_content = "Qual é a grande ideia, Cena?! Não comece a rir assim de repente, você está me assustando...",
  ui_story_5058_50581502_107_dialog_content = "Eu só tive que rir de mim mesmo. EveEmbora eu claramente tenha essas asas nas minhas costas, ainda não consegui entender o que a Deusa Denuo estava pensando, depois de todo esse tempo.",
  ui_story_5058_50581502_108_dialog_content = "Se você é uma Deusa Denuo, um inseto comum ou um semi-humano como eu, todos nós somos muito simples no fundo.",
  ui_story_5058_50581502_109_dialog_content = "E enquanto você não prejudicá-los, eles nunca atacarão sem provocação.",
  ui_story_5058_50581502_110_dialog_content = "Eles podem esquecer mil mágoas durante a noite, mas lembrarão de um único ato de bondade por toda a vida.",
  ui_story_5058_50581502_111_dialog_content = "Eles podem até esquecer suas mágoas?",
  ui_story_5058_50581502_112_dialog_content = "Cena, o que a Deusa Denuo disse a você antes de partir?",
  ui_story_5058_50581502_113_dialog_content = "Ela me abençoou com...",
  ui_story_5058_50581502_114_dialog_content = "A coragem de continuar vivendo.",
  ui_story_5058_50581601_1_dialog_content = "O que você disse?!",
  ui_story_5058_50581601_2_dialog_content = "Remover todo o hype relacionado à Deusa Denuo?",
  ui_story_5058_50581601_3_dialog_content = "Como investidores valorizados, este é o primeiro assunto que eu queria trazer à sua atenção hoje.",
  ui_story_5058_50581601_4_dialog_content = "A segunda questão que gostaria de informar é que não continuarei o desenvolvimento do Denuo Incenso e, em terceiro lugar, posso confirmar que a segunda fase do plano de expansão do resort foi, para todos os efeitos, cancelada.",
  ui_story_5058_50581601_5_dialog_content = "Você sabe mesmo o que está dizendo?",
  ui_story_5058_50581601_6_dialog_content = "Todos os três são a melhor maneira de garantir que o resort recuperará o dinheiro investido e continuará funcionando! Você consegue administrar um negócio?",
  ui_story_5058_50581601_7_dialog_content = "Heh, não se preocupe com isso agora! Pelo que parece... você tem outros planos na manga, não é mesmo, chefe?",
  ui_story_5058_50581601_8_dialog_content = "Sei que isso pode ser difícil de aceitar no início, mas após cuidadosa consideração, decidi que o Denuo Valley Resort deve operar sob uma filosofia de negócios mais consciente.",
  ui_story_5058_50581601_9_dialog_content = "Seja em marketing, serviços ou produtos de origem local, precisamos manter o conceito de sustentabilidade do vale em mente o tempo todo e seguir um princípio orientador de desenvolvimento ecológico.",
  ui_story_5058_50581601_10_dialog_content = "As atividades mencionadas podem gerar lucros a curto prazo, mas elas negligenciam o impacto que estamos causando no meio ambiente e as consequências que surgirão mais cedo ou mais tarde.",
  ui_story_5058_50581601_11_dialog_content = "É por isso que proponho que continuemos melhorando o ambiente dentro do vale e criemos um ecossistema onde Aurorianos, animais e plantas possam coexistir...",
  ui_story_5058_50581601_12_dialog_content = "Continuar melhorando o meio ambiente? Tudo isso só para tirar mais dinheiro de nós?",
  ui_story_5058_50581601_13_dialog_content = "De acordo com meus cálculos, o lucro da operação básica do resort, menos várias despesas, deve ser suficiente para suportar meu plano proposto!",
  ui_story_5058_50581601_14_dialog_content = "Você nos acha tolos? Você já recebeu tanto de nós! Você acha que isso é uma caridade?",
  ui_story_5058_50581601_15_dialog_content = "Realizei uma série de testes preliminares e estou totalmente confiante de que a nova versão do resort será um sucesso garantido! Tudo o que precisamos fazer é abrir os portões e assistir os hóspedes chegarem em massa!",
  ui_story_5058_50581601_16_dialog_content = "Primeiro, precisamos nos esforçar ao máximo para estabelecer uma boa reputação, garantir lucros para o período atual e melhorar continuamente o ambiente no vale...",
  ui_story_5058_50581601_17_dialog_content = "Assim que tivermos certeza de que o ambiente natural do vale pode ser preservado completamente, podemos construir uma reserva de vida selvagem para nossos hóspedes desfrutarem.",
  ui_story_5058_50581601_18_dialog_content = "Não apenas isso proporcionará aos nossos hóspedes uma experiência única e inovadora, como também garantirá que o resort ofereça um ambiente idílico a todos que o visitam.",
  ui_story_5058_50581601_19_dialog_content = "E com isso, nosso resort terá uma vantagem competitiva sólida sobre todos os Astra!",
  ui_story_5058_50581601_20_dialog_content = "Não é preciso dizer que tudo isso garante grandes retornos em seus investimentos a longo prazo!",
  ui_story_5058_50581601_21_dialog_content = "Hehehe... É tão bom ver você colocando suas próprias ideias em prática e seguindo em frente, Lorelei!",
  ui_story_5058_50581601_22_dialog_content = "Sempre fui uma pessoa que encoraja e apoia o espírito empreendedor quando o vejo!",
  ui_story_5058_50581601_23_dialog_content = "Even se meu investimento não trouxer retornos em breve, tudo bem para mim... Eu não me importo de esperar mais alguns dias pelo meu dinheiro.",
  ui_story_5058_50581601_24_dialog_content = "Continuarei supervisionando seu progresso, é claro, para garantir que você mantenha o foco e faça o que se propôs a alcançar. Caso contrário, eu também posso ter que retirar meu suporte.",
  ui_story_5058_50581601_25_dialog_content = "Ridículo! E o resto de vocês? Eu não acho que vocês continuarão caindo nesse projeto estúpido!",
  ui_story_5058_50581601_26_dialog_content = "Fique tranquilo. Estou feliz por ela e pelas ideias dela.",
  ui_story_5058_50581601_27_dialog_content = "No entanto... Você sabe que o que está fazendo agora é claramente uma violação do contrato que assinamos, certo, Lorelei?",
  ui_story_5058_50581601_28_dialog_content = "De acordo com os termos, você deve nos pagar o triplo pela violação.",
  ui_story_5058_50581601_29_dialog_content = "Claro, isso mesmo. Você consegue pagar, Lorelei?",
  ui_story_5058_50581601_30_dialog_content = "Eu...",
  ui_story_5058_50581601_31_dialog_content = "A-Apenas três vezes mais?! Ahhh... O que eu vou dizer ao Pai agora?!",
  ui_story_5058_50581601_32_dialog_content = "Esfregar sal nas feridas de um amigo fiel e você certamente encontrará um fim pegajoso.",
  ui_story_5058_50581601_33_dialog_content = "Se você nos tivesse dito isso desde o início, Lorelei, nunca teríamos investido...",
  ui_story_5058_50581601_34_dialog_content = "Sim, eu também não...",
  ui_story_5058_50581601_35_dialog_content = "Não se preocupe, Lorelei!",
  ui_story_5058_50581601_36_dialog_content = "Quem vocês pensam que estão menosprezando? Não é como se nós não pudéssemos pagar por isso—",
  ui_story_5058_50581601_37_dialog_content = "...",
  ui_story_5058_50581601_38_dialog_content = "Aham... Tenho certeza absoluta de que minha filha consegue lidar com isso com um braço amarrado atrás das costas!",
  ui_story_5058_50581601_39_dialog_content = "(Mãe...)",
  ui_story_5058_50581601_40_dialog_content = "Peço desculpas sinceras a todos vocês e estou plenamente ciente de que minhas ações violaram os termos do nosso contrato original.",
  ui_story_5058_50581601_41_dialog_content = "Assumo total responsabilidade e não vou tentar passar a culpa.",
  ui_story_5058_50581601_42_dialog_content = "Mas também preciso que todos vocês acreditem que minha determinação em reconstruir o vale é tão inabalável quanto minha determinação em administrar um excelente resort!",
  ui_story_5058_50581601_43_dialog_content = "Tenho total confiança de que posso garantir melhores retornos em seus investimentos. É só que... você pode precisar esperar um pouco mais do que o esperado.",
  ui_story_5058_50581601_44_dialog_content = "Eu entendo e aplaudo você.",
  ui_story_5058_50581601_45_dialog_content = "Mas vou pedir ao meu advogado para lhe enviar uma conta, Lorelei.",
  ui_story_5058_50581601_46_dialog_content = "Não diga que nunca te demos uma chance... Comece a se preocupar com sua falência.",
  ui_story_5058_50581601_47_dialog_content = "Laurie...",
  ui_story_5058_50581601_48_dialog_content = "Ufa... Está tudo bem, mãe. Eu imaginei que as coisas poderiam virar assim.",
  ui_story_5058_50581601_49_dialog_content = "Mas ainda não acabou. Eu não vou usar a fortuna da família para cobrir a diferença até pelo menos pedir ajuda à guilda primeiro...",
  ui_story_5058_50581601_50_dialog_content = "Bem, não há motivo para tentar impedir um rebelde obstinado como você.",
  ui_story_5058_50581601_51_dialog_content = "Hah, você não está errado... mas eu sei que estou fazendo a coisa certa, e isso é suficiente para mim.",
  ui_story_5058_50581601_52_dialog_content = "Eu gosto do jeito que você também não suporta aqueles velhos chatos.",
  ui_story_5058_50581601_53_dialog_content = "Eu conheço um certo otário que aparentemente tem mais do que alguns Noitium para gastar e um grupo razoavelmente grande para acompanhar.",
  ui_story_5058_50581601_54_dialog_content = "Se ela soubesse que eu investi aqui, tenho certeza de que ela estaria se esforçando ao máximo para investir ainda mais do que eu.",
  ui_story_5058_50581601_55_dialog_content = "Por favor, prometa que vai me apresentar a ela!",
  ui_story_5058_50581601_56_dialog_content = "As asas dela brilhavam como uma joia na luz solar!",
  ui_story_5058_50581601_57_dialog_content = "Puxa, eu deveria ter ido junto com vocês...",
  ui_story_5058_50581601_58_dialog_content = "Hmm, você não disse que é melhor ter um problema a menos do que uma dor de cabeça a mais, e então dormir como um tronco?",
  ui_story_5058_50581601_59_dialog_content = "É minha culpa a cama do hotel ser tão macia e cheirar tão bem? Nunca dormi em um berço tão confortável antes...",
  ui_story_5058_50581601_60_dialog_content = "Deixa pra lá... Fia e eu estamos trabalhando como especialistas seniores em animais para o resort, então ainda podemos ter a chance de conhecer a Deusa Denuo em breve.",
  ui_story_5058_50581601_61_dialog_content = "Mestre, você realmente planeja desperdiçar seus dias aqui para sempre?",
  ui_story_5058_50581601_62_dialog_content = "PlayerName, o que você ainda está fazendo por aqui conversando?",
  ui_story_5058_50581601_63_dialog_content = "Olha, eu e Carleen já juntamos um monte de adesivos!",
  ui_story_5058_50581601_64_dialog_content = "Eles realmente mudaram sua campanha de marketing — até as borboletas desses adesivos foram substituídas...",
  ui_story_5058_50581601_65_dialog_content = "Mas as regras são as mesmas de antes - basta juntar adesivos suficientes e você pode trocá-los por prêmios!",
  ui_story_5058_50581601_66_dialog_content = "Ouvimos que o grande prêmio é um passe anual para o Denuo Valley Resort.",
  ui_story_5058_50581601_67_dialog_content = "Se você não juntar adesivos suficientes, PlayerName... Eu vou simplesmente pegar Carleen na próxima vez! Nem vou me dar ao trabalho de perguntar!",
  ui_story_5058_50581601_68_dialog_content = "Você realmente iria sem mim?",
  ui_story_5058_50581601_69_dialog_content = "Aham... Olha, se você não quer ficar de fora, venha jogar Fantasy Matrix conosco!",
  ui_story_5058_50581601_70_dialog_content = "O quê? Você ainda está mexendo com aquela coisa?!",
  ui_story_5058_50581601_71_dialog_content = "Aqui vai um conselho gratuito—na próxima vez, nem pense em deixar o Sinsa projetar uma atração de parque temático...",
  ui_story_5058_50581601_72_dialog_content = "Encontrei.",
  ui_story_5058_50581601_73_dialog_content = "Cena, você já não fez o suficiente?",
  ui_story_5058_50581601_74_dialog_content = "Você finalmente pode sair conosco hoje?",
  ui_story_5058_50581601_75_dialog_content = "Senhoras, obrigado a todas pelo grande número de comentários perspicazes e sugestões que vocês propuseram para o resort!",
  ui_story_5058_50581601_76_dialog_content = "Agindo conforme seus desejos, Lorelei me pediu para acelerar os ajustes nos equipamentos e diversos serviços do resort com base em suas sugestões.",
  ui_story_5058_50581601_77_dialog_content = "Algo está diferente sobre Cena...",
  ui_story_5058_50581601_78_dialog_content = "Hã? Sério? Eu nunca mostrei às senhoras meu lado legal e competente antes?",
  ui_story_5058_50581601_79_dialog_content = "Já se conheceram?",
  ui_story_5058_50581601_80_dialog_content = "Não.",
  ui_story_5058_50581601_81_dialog_content = "Caramba... Isso foi cruel, Winona. Haha...",
  ui_story_5058_50581601_82_dialog_content = "Cena, não se deixe levar conversando com os convidados! Lembre-se, temos muito trabalho a fazer!",
  ui_story_5058_50581601_83_dialog_content = "Ah, certo... Eu quase tinha esquecido...",
  ui_story_5058_50581601_84_dialog_content = "Senhoras, preciso me retirar! Por favor, não sintam muita falta de mim - podemos relembrar os velhos tempos mais tarde!",
  ui_story_5058_50581601_85_dialog_content = "Devemos continuar esperando?",
  ui_story_5058_50581601_86_dialog_content = "Nah, ele parecia bem o suficiente para pararmos de nos preocupar.",
  ui_story_5058_50581601_87_dialog_content = "Que pena. Que tal irmos ver o Celestita?",
  ui_story_5058_50581601_88_dialog_content = "Ei, isso não é uma má ideia.",
  ui_story_5058_50581601_89_dialog_content = "Hum? Eu só saí por um minuto para pegar um sorvete de lagarto! Onde todos foram?",
  ui_story_5058_50581601_90_dialog_content = "<size=45>Esqueceram de mim de novo?!</size>",
  ui_story_5058_50581601_91_dialog_content = "A primeira vez que te levei na roda-gigante, você mal conseguia ver a vista, mesmo estando de pé.",
  ui_story_5058_50581601_92_dialog_content = "Eu lembro, eu lembro! Eu estava realmente irritado e comecei a reclamar de como a roda gigante não tinha sido projetada corretamente e que eu queria reclamar com o gerente.",
  ui_story_5058_50581601_93_dialog_content = "A equipe disse que me daria uma boneca para me manter feliz.",
  ui_story_5058_50581601_94_dialog_content = "E de todas aquelas bonecas fofas que eles pediram para você escolher, você escolheu aquele enorme esqueleto de animal em exposição!",
  ui_story_5058_50581601_95_dialog_content = "Hahaha! Eu realmente não sei o que eu estava pensando na época...",
  ui_story_5058_50581601_96_dialog_content = "Eu sinceramente não consigo acreditar... Minha pequena Laurie cresceu tanto.",
  ui_story_5058_50581601_97_dialog_content = "Mãe, obrigada por estar comigo na reunião de diretoria hoje.",
  ui_story_5058_50581601_98_dialog_content = "Se eu não tivesse você lá, acho que não teria a confiança para superar.",
  ui_story_5058_50581601_99_dialog_content = "Não seja ridícula — você é minha filha! Que tipo de mãe não apoiaria sua filha, hein?!",
  ui_story_5058_50581601_100_dialog_content = "E eu sei que mesmo que eu não estivesse lá para ficar ao seu lado, você tem em si a capacidade de alcançar tudo o que você se propõe a fazer.",
  ui_story_5058_50581601_101_dialog_content = "Como quando você corajosamente pediu à Deusa Denuo um antídoto e me salvou...",
  ui_story_5058_50581601_102_dialog_content = "Se não fosse por você, talvez eu nunca tivesse conseguido fazer as pazes com a Deusa Denuo.",
  ui_story_5058_50581601_103_dialog_content = "De fato. Talvez toda essa experiência tenha sido uma oportunidade concedida a nós pelos céus, ou talvez pela própria Deusa Denuo...",
  ui_story_5058_50581601_104_dialog_content = "Eu estava preso em um longo e doloroso pesadelo — um sonho no qual fui forçado a encarar meu verdadeiro eu.",
  ui_story_5058_50581601_105_dialog_content = "Foi então que percebi que não tinha sido uma boa mãe para você...",
  ui_story_5058_50581601_106_dialog_content = "Eu não te contei sobre sua cidade natal e seus entes queridos, e eu até estava atrapalhando seu crescimento...",
  ui_story_5058_50581601_107_dialog_content = "Mãe, não fale isso sobre você mesma!",
  ui_story_5058_50581601_108_dialog_content = "Sou a garota mais sortuda do mundo, e sabe por quê? Porque eu tenho duas mães gentis e lindas!",
  ui_story_5058_50581601_109_dialog_content = "Epa, epa, epa... Se vocês duas querem ter uma conversa sincera entre mãe e filha, tudo bem, mas por que estão me envolvendo nisso?",
  ui_story_5058_50581601_110_dialog_content = "Eu disse às senhoras que voltaria logo! Essas lindas garotas estão me esperando, pelo amor de Deus!",
  ui_story_5058_50581601_111_dialog_content = "Claro que eu tinha que te arrastar junto.",
  ui_story_5058_50581601_112_dialog_content = "Você esqueceu a promessa entre eu, você e Coco?",
  ui_story_5058_50581601_113_dialog_content = "Promessa? Que promessa?",
  ui_story_5058_50581601_114_dialog_content = "Ah, está prestes a começar... Três... dois...",
  ui_story_5058_50581601_115_dialog_content = "Um!",
  ui_story_5058_50581601_116_dialog_content = "<color=#e8d9bb>Whoosh-Bang!</color>",
  ui_story_5058_50581601_117_dialog_content = "É com...",
  ui_story_5058_50581601_118_dialog_content = "Um show de fogos de artifício?",
  ui_story_5058_50581601_119_dialog_content = "<color=#e8d9bb>Whoosh—Bum, bum!</color>",
  ui_story_5058_50581601_120_dialog_content = "\"Os fogos de artifício subiram ao céu noturno como borboletas esvoaçantes...\"",
  ui_story_5058_50581601_121_dialog_content = "Os fogos de artifício em Lumópolis são realmente tão bonitos?",
  ui_story_5058_50581601_122_dialog_content = "Ouvi dizer que são ainda mais bonitas do que borboletas!",
  ui_story_5058_50581601_123_dialog_content = "Mãe, eu também quero ir até Lumópolis para assistir aos fogos de artifício!",
  ui_story_5058_50581601_124_dialog_content = "Mas Lumópolis está muito, muito longe!",
  ui_story_5058_50581601_125_dialog_content = "Do que ter medo? Vamos assistir juntos! Eu sei que chegaremos lá um dia!",
  ui_story_5058_50581601_126_dialog_content = "Sério? Vocês dois não sentem falta de casa?",
  ui_story_5058_50581601_127_dialog_content = "Onde quer que você esteja, Coco, é onde minha casa está.",
  ui_story_5058_50581601_128_dialog_content = "Ei! Você está tentando roubar minha mãe, Cena?! Nem pense nisso! A mãe é toda minha!",
  ui_story_5058_50581601_129_dialog_content = "Eu nem estou tentando dizer que a Coco é minha mãe, sabe!",
  ui_story_5058_50581601_130_dialog_content = "E-Ela é... uma senhora adorável!",
  ui_story_5058_50581601_131_dialog_content = "Haha, parece divertido ter um filho da mesma idade que você!",
  ui_story_5058_50581601_132_dialog_content = "Sra. Coco! A senhora mais encantadora que eu conheço!",
  ui_story_5058_50581601_133_dialog_content = "Luke, faz tanto tempo que não tenho notícias suas.",
  ui_story_5058_50581601_134_dialog_content = "\"Você nunca vai adivinhar onde estou trabalhando agora!\"",
  ui_story_5058_50581601_X134_dialog_content = "\"Estou trabalhando no Denuo Valley Resort—o lugar que você mencionou em sua carta!\"",
  ui_story_5058_50581601_135_dialog_content = "Se eu te dissesse que o Vale Denuo é a misteriosa cidade natal que mencionei antes,\n o quão chocado você ficaria?",
  ui_story_5058_50581601_136_dialog_content = "\"Mas eu tenho algo ainda mais chocante para te contar...\"",
  ui_story_5058_50581601_X136_dialog_content = "\"Eu vi a Deusa Denuo!\"",
  ui_story_5058_50581601_137_dialog_content = "E isso mesmo, EU SOBREVIVI! Eu sei o que você está pensando agora, \"Por que ele escreveu que ainda está vivo em letras maiúsculas?\"",
  ui_story_5058_50581601_138_dialog_content = "Infelizmente, não consigo colocar todos os detalhes em uma única carta...",
  ui_story_5058_50581601_139_dialog_content = "Se você tiver tempo, simplesmente precisa vir me visitar no resort. Estarei te esperando e pronto para compartilhar todas as minhas experiências desde que voltei para minha cidade natal.",
  ui_story_5058_50581601_140_dialog_content = "\"EveToda noite antes de fechar os olhos para dormir, eu fico ansioso pelo que o amanhã pode trazer. Parece...\"",
  ui_story_5058_50581601_X140_dialog_content = "<size=45>\"Incrível!\"</size>"
}
return config
